INSERT INTO daily_logs VALUES(155,2,'2025-08-01',112.3499999999999944,112,2.399999999999999912,8.5,2039,2446.799999999999727,1810,760,97,182,77,636.7999999999997271,'步数: 9168; 骑行: 10min; 爬楼: 16层','今日热量摄入在减重目标范围内，配合充足的运动量、良好的睡眠和饮水，整体表现积极。但蛋白质摄入量相对不足（97克），对于112公斤的体重来说，建议进一步增加优质蛋白的摄入，并提高新鲜蔬菜的比例，以优化营养结构、增强饱腹感并支持肌肉维护。','2025-08-20 09:54:19','2025-08-22 03:38:28');
INSERT INTO daily_logs VALUES(156,2,'2025-08-02',111.7999999999999972,112.2999999999999972,2,8.5,2034,2440.799999999999727,600,490,18,104,14.5,1840.799999999999728,'步数: 8276; 类型: 快走+慢跑','当日总热量摄入极低（1050千卡），有利于体重下降，但蛋白质摄入量（48克）远低于体重111.8公斤所需，可能导致肌肉流失和营养不均。建议在逐步提高总热量摄入的同时，重点增加优质蛋白质食物。运动量良好，睡眠充足，水分摄入可适量增加。','2025-08-20 09:54:19','2025-08-22 03:39:43');
INSERT INTO daily_logs VALUES(157,2,'2025-08-03',110.1500000000000056,112,2,8,2017,2420.40000000000009,1250,300,53,145,47,1170.40000000000009,'步数: 10239','今日总热量摄入为1250千卡，蛋白质53克，碳水化合物145克，脂肪47克。根据您110.15kg的体重和8小时睡眠，以及10239步的活动量，您的基础代谢和活动消耗大致估算为300千卡。从营养构成来看，碳水化合物占比略高，而蛋白质摄入相对较低。建议下一餐增加优质蛋白质的摄入，并注意整体饮食的均衡性，以支持健康和体重管理。','2025-08-20 09:54:19','2025-08-22 03:42:01');
INSERT INTO daily_logs VALUES(158,2,'2025-08-04',109.0999999999999944,112,2.399999999999999912,7.5,2007,2408.40000000000009,1500,450,85,155,58,908.400000000000091,'步数: 12838; 爬楼: 16层','今日总热量摄入1500千卡，主要来自碳水化合物，蛋白质和脂肪摄入相对均衡。活动量较大，消耗约450千卡。水分摄入充足，睡眠质量良好。建议下一餐适量增加蛋白质摄入，并留意烹饪方式，减少油炸。整体饮食健康，但可进一步优化。','2025-08-20 09:54:19','2025-08-22 03:48:49');
INSERT INTO daily_logs VALUES(159,2,'2025-08-05',108.3499999999999944,112.2000000000000028,2.5,7.5,1999,2398.799999999999727,1505,450,110,150,52,893.7999999999997271,'步数: 13244; 爬楼: 16层','今日总热量摄入为1505千卡，蛋白质摄入充足（120克），碳水化合物和脂肪摄入适中。水分摄入2.5升，睡眠7.5小时，运动量（13244步，16层楼）估算消耗约450千卡，表现良好。整体饮食营养均衡，建议继续保持。注意饮食烹饪方式，尽量选择蒸、煮、烤等低油方式。','2025-08-20 09:54:19','2025-08-22 03:49:05');
INSERT INTO daily_logs VALUES(160,2,'2025-08-06',107.4000000000000056,112,2.399999999999999912,7.5,1990,2388,1290,450,95,135,40,1098,'步数: 13232; 爬楼: 16层','今日总热量摄入为1290大卡，蛋白质、碳水化合物和脂肪摄入相对均衡。运动方面，步数和爬楼量可观，消耗了约450大卡。整体饮食结构良好，但考虑到您的体重，可以适当增加热量摄入，特别是增加一些优质脂肪和复合碳水化合物，以更好地支持身体活动和新陈代谢。请注意保持充足的水分摄入，并保证规律的睡眠。','2025-08-20 09:54:19','2025-08-22 03:49:14');
INSERT INTO daily_logs VALUES(161,2,'2025-08-07',107,112.2999999999999972,2.5,7.5,1986,2383.199999999999819,1300,600,85,110,53,1083.199999999999819,'类型: 力量训练; 步数: 12162; 爬楼: 16层','今日总热量摄入1300千卡，蛋白质85克，碳水化合物110克，脂肪53克。运动消耗约600千卡。整体营养摄入相对均衡，且有足够的蛋白质满足身体需求。但今日总热量摄入低于一般成年人维持体重所需，且可能未充分考虑午餐的实际热量，建议午餐热量评估更精确，并结合整体运动量和基础代谢，确保热量摄入满足身体需求，避免长期热量赤字影响健康。','2025-08-20 09:54:19','2025-08-22 03:50:12');
INSERT INTO daily_logs VALUES(162,2,'2025-08-08',106.0499999999999972,111.2999999999999972,2.399999999999999912,7.5,1976,2371.199999999999819,1060,400,75,80,50,1311.199999999999818,'步数: 12251; 爬楼: 16层','今日总热量摄入约1440千卡，蛋白质75克，碳水化合物80克，脂肪50克。午餐和晚餐营养搭配较为均衡，但早餐部分数据缺失，无法准确估算。全天饮水2.4升，睡眠7.5小时，运动量适中，步数超万，爬楼层也较多，消耗热量估算约400千卡。整体而言，今日摄入的营养素比例尚可，但早餐的分析不完整，需注意补充。建议关注早餐的营养构成，保证全面摄入蛋白质、复合碳水化合物和健康的脂肪。','2025-08-20 09:54:19','2025-08-22 03:50:43');
INSERT INTO daily_logs VALUES(163,2,'2025-08-09',106.5,111.4000000000000056,2,8,1981,2727.199999999999819,1385,500,95,125,55,1342.199999999999818,'[{"id":"0-0","type":"散步+小跑","amount":"10212"}]','当日总热量摄入1385千卡，总蛋白质95克，碳水化合物125克，脂肪55克。运动消耗约500千卡。整体营养摄入较为均衡，蛋白质比例充足，但碳水化合物和脂肪摄入相对较高，建议适当调整，控制总热量摄入，增加蔬菜和水果的比例以提升整体营养密度。','2025-08-20 09:54:19','2025-08-22 03:53:18');
INSERT INTO daily_logs VALUES(164,2,'2025-08-10',106.8499999999999944,110,2,7.5,1984,2380.799999999999727,1320,200,65,170,36,1060.799999999999728,'步数: 4000; 类型: 休息日散步','今日总能量摄入为1320大卡，蛋白质65克，碳水化合物170克，脂肪36克。总体能量摄入相对较低，但蛋白质和脂肪比例尚可。活动量不大，仅为休息日散步。建议适当增加餐食份量，特别是增加优质蛋白质来源，以更好地支持身体机能和维持饱腹感。同时，可以考虑增加中高强度运动，以提高能量消耗和促进整体健康。','2025-08-20 09:54:19','2025-08-22 03:50:21');
INSERT INTO daily_logs VALUES(165,2,'2025-08-11',106.75,110.2000000000000028,2.399999999999999912,8,1983,2979.59999999999991,1110,550,65,102,49,1869.59999999999991,'步数: 17774; 骑行: 4.25km; 爬楼: 16层','今日饮食摄入热量1000大卡，蛋白质65克，碳水102克，脂肪49克。运动消耗约550大卡。整体来看，营养摄入基本均衡，但考虑到您106.75kg的体重，此热量摄入偏低，可能不利于能量储备和肌肉维持。建议在现有基础上适度增加热量摄入，并保持高蛋白、适量碳水和健康脂肪的比例。运动量较为可观，请注意补充水分。','2025-08-20 09:54:19','2025-08-22 04:05:30');
INSERT INTO daily_logs VALUES(166,2,'2025-08-12',105.9500000000000028,110.2999999999999972,2.399999999999999912,7.5,1975,2820,1370,450,110,200,45,1450,'[{"id":"0-1","type":"有氧yun运动","amount":"30min"},{"id":"0-2","type":"步数","amount":"13895"},{"id":"0-3","type":"爬楼","amount":"16层"}]','今日摄入热量适中，蛋白质、碳水化合物和脂肪比例相对均衡。运动量充足，尤其步数和爬楼对心肺功能和下肢力量有益。建议继续保持均衡饮食和规律运动，关注水分摄入，以更好地支持健康生活方式。','2025-08-20 09:54:19','2025-08-22 04:04:52');
INSERT INTO daily_logs VALUES(167,2,'2025-08-13',105.6500000000000056,109.2000000000000028,2.399999999999999912,7.5,1972,2816.40000000000009,1460,450,110,170,45,1356.40000000000009,'步数: 12829; 爬楼: 16层','今日总热量摄入1460大卡，蛋白质105克，碳水化合物170克，脂肪45克。活动量较大，消耗约450大卡。整体饮食结构尚可，但早餐和晚餐的碳水化合物比例稍高，建议适当调整，增加蔬菜和优质蛋白质的摄入，以优化营养均衡。水分摄入充足，睡眠质量良好。','2025-08-20 09:54:19','2025-08-22 04:04:49');
INSERT INTO daily_logs VALUES(168,2,'2025-08-14',105,109,2.200000000000000178,7,1966,2859.199999999999819,1675,400,105,200,60,1184.199999999999818,'步数: 13564; 爬楼: 16层','今日总摄入热量约为1675大卡，蛋白质105克，碳水化合物200克，脂肪60克。水分摄入2.2升，睡眠7小时，活动量适中（步数13564，爬楼16层），这些都对健康有益。早餐和午餐营养搭配较好，晚餐以沙拉为主，热量稍高。整体能量摄入与消耗接近，但仍可考虑优化膳食结构，增加蔬菜和粗粮比例，减少高油、高盐的烹饪方式，以更利于长期健康管理。','2025-08-20 09:54:19','2025-08-22 04:04:38');
INSERT INTO daily_logs VALUES(169,2,'2025-08-15',104.5499999999999972,109.2999999999999972,2,7.5,1961,2803.199999999999819,1410,450,85,190,35,1393.199999999999818,'步数: 10787; 爬楼: 16层','今日总能量摄入为1410大卡，运动消耗约450大卡。饮食整体较为均衡，提供了丰富的蛋白质和碳水化合物，脂肪摄入适中。建议在控制总热量的前提下，适度增加蔬菜和优质脂肪的摄入，以提升营养密度。充足的水分和良好的睡眠（7.5小时）也对健康有益。','2025-08-20 09:54:19','2025-08-22 04:04:34');
INSERT INTO daily_logs VALUES(170,2,'2025-08-16',104.4000000000000056,109.5999999999999944,2,7,1960,2852,1185,350,80,145,30,1667,'类型: 力量训练; 循环: 3; 步数: 10000','今日热量摄入适中，但蛋白质和碳水化合物摄入量略低于平均水平。虽然进行了力量训练并达到了10000步的目标，但整体热量消耗相对不高。建议在保证均衡饮食的同时，适当增加蛋白质和优质碳水化合物的摄入，以支持身体恢复和肌肉生长。水分摄入充足，睡眠质量良好，应继续保持。','2025-08-20 09:54:19','2025-08-22 04:04:31');
INSERT INTO daily_logs VALUES(171,2,'2025-08-17',104.4000000000000056,109.0999999999999944,2,7.5,1960,2652,935,450,45,100,15,1717,'类型: 力量训练; 循环: 3; 步数: 10000','今日热量摄入相对较低，但营养构成较为均衡。建议在早餐部分补充蛋白质和脂肪的估算，以更全面了解早餐的营养价值。运动消耗良好，结合整体能量平衡，今日总体健康评价良好。','2025-08-20 09:54:19','2025-08-22 04:04:26');
INSERT INTO daily_logs VALUES(172,2,'2025-08-18',104.75,109.2000000000000028,2.399999999999999912,5.5,1963,2855.59999999999991,1820,650,148,195,60,1035.599999999999909,'步数: 13260; 爬楼: 16层; 其他: 全身按摩1小时','今日饮食能量摄入充足，蛋白质、碳水化合物和脂肪比例相对均衡。运动量可观，消耗了部分热量。睡眠时间偏短，可能影响身体恢复。建议关注规律作息，以优化整体健康状态。','2025-08-20 09:54:19','2025-08-22 04:04:22');
INSERT INTO daily_logs VALUES(173,2,'2025-08-19',104,109,2.399999999999999912,7,1956,2547.199999999999819,1345,500,58,70,20,1202.199999999999818,'[{"id":"0-0","type":"步数","amount":"13686"},{"id":"0-1","type":"爬楼","amount":"16层"}]','当日总热量摄入1345大卡，蛋白质58克，碳水化合物70克，脂肪20克。午餐和晚餐的蛋白质估算不准确。运动方面，13686步大约消耗350-450大卡，16层楼爬升消耗约50-80大卡。整体热量摄入低于一般成人推荐量，但食物组合仍需注意蛋白质的足量摄入，特别是晚餐。建议优先保证优质蛋白质来源，并细化各餐食材与份量以更精确地评估营养。','2025-08-20 09:54:19','2025-08-22 04:04:19');
INSERT INTO daily_logs VALUES(174,2,'2025-08-20',103.7999999999999972,109,2.399999999999999912,7,1954,2594.799999999999727,1250,335,90,120,40,1344.799999999999728,'[{"id":"1755776740088","type":"步行","amount":"7188"}]','今日总能量摄入为1250千卡，蛋白质90克，碳水化合物120克，脂肪40克。约7188步的步行消耗约335千卡。整体饮食结构以蛋白质和蔬菜为主，热量控制较好，但如能适当增加健康脂肪和复合碳水化合物的摄入，并维持规律运动，将有助于更全面的营养均衡。水分摄入2.4升，睡眠7小时，符合基本健康建议。','2025-08-20 09:54:19','2025-08-22 04:04:16');
