u6790\u3002\u4ece8\u670810\u65e5\u8d77\uff0c\u8bb0\u5f55\u8d28\u91cf\u663e\u8457\u63d0\u5347\uff0c\u5f00\u59cb\u63d0\u4f9b\u70ed\u91cf\u548c\u5b8f\u91cf\u6570\u636e\uff0c\u5c55\u73b0\u51fa\u79ef\u6781\u7684\u6539\u53d8\u3002\u6574\u4f53\u996e\u98df\u7ed3\u6784\u8d8b\u5411\u6e05\u6de1\u3001\u9ad8\u86cb\u767d\u548c\u5168\u8c37\u7269\uff0c\u8fd9\u662f\u4e00\u4e2a\u826f\u597d\u7684\u8f6c\u53d8\u3002", "positive": "\u4ece8\u670810\u65e5\u5f00\u59cb\uff0c\u7528\u6237\u79ef\u6781\u8bb0\u5f55\u6bcf\u9910\u70ed\u91cf\u548c\u5b8f\u91cf\u8425\u517b\u7d20\uff0c\u98df\u7269\u9009\u62e9\u4e0a\u504f\u5411\u9ad8\u86cb\u767d\uff08\u5982\u9c7c\u3001\u867e\u3001\u725b\u8089\u3001\u9e21\u86cb\uff09\uff0c\u642d\u914d\u7c97\u7cae\uff08\u7d2b\u7c73\u996d\u3001\u7cd9\u7c73\u996d\u3001\u7ea2\u85af\u3001\u7389\u7c73\u3001\u835e\u9ea6\u9762\uff09\u548c\u5927\u91cf\u852c\u83dc\uff0c\u907f\u514d\u4e86\u9ad8\u7cd6\u3001\u9ad8\u8102\u7684\u52a0\u5de5\u98df\u54c1\uff0c\u8fd9\u662f\u4e00\u4e2a\u503c\u5f97\u80af\u5b9a\u7684\u8fdb\u6b65\u3002", "improvement": "1. \u65e9\u671f\u6570\u636e\u7f3a\u5931\u662f\u6700\u5927\u7684\u95ee\u9898\uff0c\u963b\u788d\u4e86\u5bf9\u521d\u59cb\u9636\u6bb5\u996e\u98df\u7684\u8bc4\u4f30\u3002\u672a\u6765\u5fc5\u987b\u786e\u4fdd\u6240\u6709\u5173\u952e\u6307\u6807\u7684\u5b8c\u6574\u8bb0\u5f55\u3002\n2. \u6bcf\u65e5\u603b\u70ed\u91cf\u6444\u5165\u6709\u65f6\u8fc7\u4f4e\uff08\u4f8b\u59828\u670817\u65e5\u4ec5935 kcal\uff09\uff0c\u957f\u671f\u53ef\u80fd\u5bfc\u81f4\u57fa\u7840\u4ee3\u8c22\u4e0b\u964d\uff0c\u4e0d\u5229\u4e8e\u53ef\u6301\u7eed\u51cf\u91cd\u548c\u5065\u5eb7\u3002\n3. \u5b8f\u91cf\u8425\u517b\u7d20\u6bd4\u4f8b\u867d\u6709\u6539\u5584\uff0c\u4f46\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u5076\u5c14\u4ecd\u663e\u4e0d\u8db3\uff0c\u5c24\u5176\u662f\u5728\u9ad8\u5f3a\u5ea6\u8fd0\u52a8\u65e5\uff0c\u53ef\u80fd\u5f71\u54cd\u8fd0\u52a8\u8868\u73b0\u548c\u6062\u590d\u3002\n4. \u5c3d\u7ba1\u6709\u5c11\u91cf\u9171\u6c41\u63d0\u53ca\uff0c\u4f46\u5065\u5eb7\u8102\u80aa\u6765\u6e90\uff08\u5982\u575a\u679c\u3001\u725b\u6cb9\u679c\u3001\u6a44\u6984\u6cb9\uff09\u7684\u79cd\u7c7b\u548c\u6444\u5165\u91cf\u53ef\u8fdb\u4e00\u6b65\u4f18\u5316\u548c\u591a\u6837\u5316\u3002", "macroDistribution": {"proteinPercentage": 26.61, "carbsPercentage": 45.93, "fatPercentage": 27.46, "comment": "\u57fa\u4e8e\u6709\u5b8f\u91cf\u6570\u636e\u8bb0\u5f55\u768412\u5929\u5e73\u5747\u503c\uff0c\u4f60\u7684\u5b8f\u91cf\u8425\u517b\u7d20\u5206\u914d\u4e3a\uff1a\u86cb\u767d\u8d2826.61%\u3001\u78b3\u6c34\u5316\u5408\u726945.93%\u3001\u8102\u80aa27.46%\u3002\u8fd9\u662f\u4e00\u4e2a\u5bf9\u51cf\u8102\u76ee\u6807\u76f8\u5bf9\u5065\u5eb7\u7684\u6bd4\u4f8b\uff0c\u86cb\u767d\u8d28\u6444\u5165\u5145\u8db3\u6709\u52a9\u4e8e\u808c\u8089\u4fdd\u6301\u548c\u9971\u8179\u611f\uff0c\u8102\u80aa\u6444\u5165\u9002\u4e2d\u3002\u7136\u800c\uff0c\u5e94\u8b66\u60d5\u603b\u70ed\u91cf\u8fc7\u4f4e\u5bf9\u5b8f\u91cf\u6bd4\u4f8b\u7684\u5f71\u54cd\uff0c\u786e\u4fdd\u662f\u5728\u8db3\u591f\u603b\u70ed\u91cf\u57fa\u7840\u4e0a\u7684\u5065\u5eb7\u6bd4\u4f8b\u3002"}}, "achievements": ["\u572822\u5929\u5185\u6210\u529f\u51cf\u91cd10.25\u516c\u65a4\uff0c\u8fd9\u662f\u4e00\u4e2a\u663e\u8457\u7684\u6210\u5c31\u3002", "\u8170\u56f4\u51cf\u5c113.0\u5398\u7c73\uff0c\u8868\u660e\u4f53\u8102\u7387\u6709\u6240\u4e0b\u964d\u3002", "\u4ece\u6700\u521d\u201c\u4e45\u5750\u4e0d\u52a8\u201d\u7684\u751f\u6d3b\u65b9\u5f0f\u8f6c\u53d8\u4e3a\u6bcf\u65e5\u79ef\u6781\u8fdb\u884c\u9ad8\u6b65\u6570\u6d3b\u52a8\uff08\u5e73\u5747\u8d85\u8fc710,000\u6b65\uff09\u548c\u89c4\u5f8b\u7684\u722c\u697c\u3001\u9a91\u884c\uff0c\u5e76\u5f15\u5165\u4e86\u529b\u91cf\u8bad\u7ec3\u3002", "\u996e\u98df\u8bb0\u5f55\u7684\u8d28\u91cf\u5728\u540e\u671f\u663e\u8457\u63d0\u5347\uff0c\u5f00\u59cb\u8be6\u7ec6\u8bb0\u5f55\u70ed\u91cf\u548c\u5b8f\u91cf\u8425\u517b\u7d20\uff0c\u663e\u793a\u4e86\u5bf9\u81ea\u6211\u7ba1\u7406\u7684\u4e25\u8083\u6001\u5ea6\u3002", "\u98df\u7269\u9009\u62e9\u8d8b\u4e8e\u5065\u5eb7\uff0c\u504f\u597d\u9ad8\u86cb\u767d\u3001\u7c97\u7cae\u548c\u852c\u83dc\uff0c\u51cf\u5c11\u4e86\u52a0\u5de5\u98df\u54c1\u7684\u6444\u5165\u3002"], "actionableTips": ["**\u7a33\u5b9a\u5361\u8def\u91cc\u6444\u5165**\uff1a\u907f\u514d\u6781\u4f4e\u70ed\u91cf\u6444\u5165\u65e5\uff08\u5982\u4f4e\u4e8e1200-1500\u5927\u5361\uff09\uff0c\u8fd9\u53ef\u80fd\u635f\u5bb3\u4ee3\u8c22\u5e76\u5bfc\u81f4\u8425\u517b\u4e0d\u826f\u3002\u8ba1\u7b97\u5e76\u575a\u6301\u4e00\u4e2a\u53ef\u6301\u7eed\u7684\u3001\u9002\u5ea6\u7684\u5361\u8def\u91cc\u7f3a\u53e3\uff08\u4f8b\u5982\uff0c\u6bd4TDEE\u4f4e500-750\u5927\u5361\uff09\u3002", "**\u4f18\u5316\u5b8f\u91cf\u914d\u6bd4\u7cbe\u51c6\u5ea6**\uff1a\u5728\u8bb0\u5f55\u5b8f\u91cf\u65f6\uff0c\u5c3d\u91cf\u7cbe\u7ec6\u5316\u98df\u7269\u5206\u91cf\uff0c\u786e\u4fdd\u86cb\u767d\u8d28\u6444\u5165\u8fbe\u5230\u6bcf\u516c\u65a4\u4f53\u91cd1.6-2.2\u514b\uff0c\u4ee5\u6700\u5927\u5316\u808c\u8089\u4fdd\u7559\u5e76\u63d0\u9ad8\u9971\u8179\u611f\u3002\u78b3\u6c34\u5316\u5408\u7269\u548c\u5065\u5eb7\u8102\u80aa\u7684\u6444\u5165\u91cf\u4e5f\u8981\u6839\u636e\u4f60\u7684\u80fd\u91cf\u6c34\u5e73\u548c\u8fd0\u52a8\u91cf\u52a8\u6001\u8c03\u6574\u3002", "**\u63d0\u9ad8\u7761\u7720\u8d28\u91cf\u548c\u65f6\u957f**\uff1a\u5c06\u6bcf\u65e5\u7761\u7720\u76ee\u6807\u8bbe\u5b9a\u57287.5-8.5\u5c0f\u65f6\uff0c\u5e76\u5efa\u7acb\u89c4\u5f8b\u7684\u4f5c\u606f\u65f6\u95f4\u3002\u7761\u89c9\u524d\u907f\u514d\u84dd\u5149\u66b4\u9732\uff0c\u521b\u9020\u826f\u597d\u7684\u7761\u7720\u73af\u5883\u3002", "**\u591a\u6837\u5316\u5065\u5eb7\u8102\u80aa\u6765\u6e90**\uff1a\u5728\u73b0\u6709\u996e\u98df\u57fa\u7840\u4e0a\uff0c\u589e\u52a0\u5065\u5eb7\u8102\u80aa\u7684\u6444\u5165\uff0c\u5982\u4e00\u5c0f\u628a\u575a\u679c\u3001\u534a\u4e2a\u725b\u6cb9\u679c\u3001\u6216\u5728\u6c99\u62c9\u4e2d\u52a0\u5165\u4e00\u52fa\u6a44\u6984\u6cb9\uff0c\u8fd9\u6709\u52a9\u4e8e\u6fc0\u7d20\u5e73\u8861\u548c\u8102\u6eb6\u6027\u7ef4\u751f\u7d20\u5438\u6536\u3002", "**\u4fdd\u6301\u996e\u6c34\u5145\u8db3**\uff1a\u5c06\u6bcf\u65e5\u996e\u6c34\u91cf\u63d0\u9ad8\u52302.5-3.0\u5347\uff0c\u5c24\u5176\u662f\u5728\u8fd0\u52a8\u65e5\uff0c\u786e\u4fdd\u8eab\u4f53\u5904\u4e8e\u6700\u4f73\u7684\u6c34\u5408\u72b6\u6001\u3002", "**\u5b8c\u5584\u8bb0\u5f55\u5b8c\u6574\u6027**\uff1a\u786e\u4fdd\u4ece\u7b2c\u4e00\u5929\u5f00\u59cb\u6240\u6709\u6307\u6807\uff0c\u7279\u522b\u662f\u5b8f\u91cf\u8425\u517b\u7d20\u548c\u5b9e\u9645\u6444\u5165\uff0c\u90fd\u6709\u5b8c\u6574\u4e14\u51c6\u786e\u7684\u8bb0\u5f55\uff0c\u8fd9\u5bf9\u4e8e\u6559\u7ec3\u7ed9\u51fa\u7cbe\u786e\u6307\u5bfc\u81f3\u5173\u91cd\u8981\u3002"], "recommendedSuperfoods": [{"food": "\u725b\u6cb9\u679c", "reason": "\u5bcc\u542b\u5065\u5eb7\u5355\u4e0d\u9971\u548c\u8102\u80aa\u3001\u81b3\u98df\u7ea4\u7ef4\u548c\u591a\u79cd\u7ef4\u751f\u7d20\u77ff\u7269\u8d28\uff0c\u80fd\u589e\u52a0\u9971\u8179\u611f\uff0c\u6709\u76ca\u5fc3\u810f\u5065\u5eb7\uff0c\u5e76\u5e2e\u52a9\u5438\u6536\u5176\u4ed6\u8102\u6eb6\u6027\u8425\u517b\u7d20\u3002\u53ef\u4ee5\u4f5c\u4e3a\u6c99\u62c9\u6216\u65e9\u9910\u7684\u4f18\u8d28\u8102\u80aa\u6765\u6e90\u3002"}, {"food": "\u5947\u4e9a\u7c7d\u6216\u4e9a\u9ebb\u7c7d", "reason": "\u662f\u690d\u7269\u6027Omega-3\u8102\u80aa\u9178\uff08ALA\uff09\u3001\u81b3\u98df\u7ea4\u7ef4\u548c\u86cb\u767d\u8d28\u7684\u6781\u4f73\u6765\u6e90\u3002\u6709\u52a9\u4e8e\u80a0\u9053\u5065\u5eb7\u3001\u964d\u4f4e\u708e\u75c7\uff0c\u5e76\u589e\u52a0\u9971\u8179\u611f\u3002\u53ef\u52a0\u5165\u71d5\u9ea6\u7ca5\u3001\u9178\u5976\u6216\u6c99\u62c9\u4e2d\u3002"}, {"food": "\u6d46\u679c\uff08\u5982\u84dd\u8393\u3001\u8986\u76c6\u5b50\uff09", "reason": "\u5bcc\u542b\u6297\u6c27\u5316\u5242\u3001\u7ef4\u751f\u7d20\u548c\u81b3\u98df\u7ea4\u7ef4\uff0c\u4f46\u7cd6\u5206\u542b\u91cf\u76f8\u5bf9\u8f83\u4f4e\u3002\u53ef\u4ee5\u6ee1\u8db3\u5bf9\u751c\u98df\u7684\u6e34\u671b\uff0c\u540c\u65f6\u63d0\u4f9b\u4e30\u5bcc\u7684\u5fae\u91cf\u5143\u7d20\uff0c\u662f\u5065\u5eb7\u7684\u96f6\u98df\u9009\u62e9\u3002"}, {"food": "\u5e0c\u814a\u9178\u5976\uff08\u65e0\u7cd6\uff09", "reason": "\u86cb\u767d\u8d28\u542b\u91cf\u8fdc\u9ad8\u4e8e\u666e\u901a\u9178\u5976\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u548c\u808c\u8089\u4fee\u590d\u3002\u540c\u65f6\u63d0\u4f9b\u76ca\u751f\u83cc\uff0c\u6709\u76ca\u80a0\u9053\u5065\u5eb7\u3002\u53ef\u4f5c\u4e3a\u52a0\u9910\u6216\u8fd0\u52a8\u540e\u8865\u5145\u3002"}, {"food": "\u6df1\u8272\u7eff\u53f6\u852c\u83dc\uff08\u5982\u83e0\u83dc\u3001\u7fbd\u8863\u7518\u84dd\u3001\u82a5\u84dd\uff09", "reason": "\u5728\u73b0\u6709\u852c\u83dc\u6444\u5165\u57fa\u7840\u4e0a\uff0c\u8fdb\u4e00\u6b65\u589e\u52a0\u591a\u6837\u6027\u3002\u8fd9\u4e9b\u852c\u83dc\u5bcc\u542b\u7ef4\u751f\u7d20K\u3001A\u3001C\u3001\u53f6\u9178\u3001\u94c1\u548c\u9499\u7b49\u591a\u79cd\u5fae\u91cf\u5143\u7d20\uff0c\u4e14\u70ed\u91cf\u6781\u4f4e\uff0c\u7ea4\u7ef4\u4e30\u5bcc\uff0c\u662f\u8425\u517b\u5bc6\u5ea6\u6781\u9ad8\u7684\u98df\u7269\u3002"}], "exercisePrescription": {"recommendation": "\u9274\u4e8e\u60a8\u5df2\u4ece\u201c\u4e45\u5750\u4e0d\u52a8\u201d\u6210\u529f\u8f6c\u5411\u9ad8\u6d3b\u52a8\u91cf\uff0c\u5e76\u5f00\u59cb\u529b\u91cf\u8bad\u7ec3\uff0c\u63a5\u4e0b\u6765\u5e94\u7cfb\u7edf\u5316\u8fd0\u52a8\u8ba1\u5212\uff0c\u7ed3\u5408\u529b\u91cf\u8bad\u7ec3\u548c\u6709\u6c27\u8fd0\u52a8\uff0c\u4ee5\u4f18\u5316\u8eab\u4f53\u7ec4\u6210\u548c\u63d0\u5347\u4ee3\u8c22\u6548\u7387\u3002", "details": ["**\u529b\u91cf\u8bad\u7ec3 (3\u6b21/\u5468)**: \u5b89\u6392\u6bcf\u54683\u6b21\u5168\u8eab\u6027\u6216\u4e0a\u4e0b\u80a2\u5206\u79bb\u7684\u529b\u91cf\u8bad\u7ec3\uff0c\u6bcf\u6b2145-60\u5206\u949f\u3002\u91cd\u70b9\u5173\u6ce8\u590d\u5408\u52a8\u4f5c\u5982\u6df1\u8e72\u3001\u786c\u62c9\u3001\u5367\u63a8\u3001\u5212\u8239\u3001\u80a9\u63a8\u3002\u91c7\u7528\u6e10\u8fdb\u8d85\u8d1f\u8377\u539f\u5219\uff0c\u9010\u6b65\u589e\u52a0\u91cd\u91cf\u3001\u7ec4\u6570\u6216\u91cd\u590d\u6b21\u6570\u3002\u5728\u6709\u529b\u91cf\u8bad\u7ec3\u7684\u65e5\u5b50\uff0c\u786e\u4fdd\u8bad\u7ec3\u540e\u8865\u5145\u8db3\u591f\u86cb\u767d\u8d28\u3002", "**\u4e2d\u7b49\u5f3a\u5ea6\u6709\u6c27 (3-4\u6b21/\u5468)**: \u6bcf\u6b2130-45\u5206\u949f\uff0c\u5fc3\u7387\u4fdd\u6301\u5728\u6700\u5927\u5fc3\u7387\u768460-70%\u3002\u53ef\u9009\u62e9\u5feb\u8d70\u3001\u6162\u8dd1\u3001\u9a91\u884c\u3001\u6e38\u6cf3\u7b49\u3002\u8fd9\u4e9b\u53ef\u4ee5\u4e0e\u529b\u91cf\u8bad\u7ec3\u65e5\u9519\u5f00\u8fdb\u884c\uff0c\u6216\u8005\u5728\u529b\u91cf\u8bad\u7ec3\u540e\u8fdb\u884c20-30\u5206\u949f\u3002", "**\u7ef4\u6301\u65e5\u5e38\u6d3b\u52a8\u91cf (NEAT)**: \u7ee7\u7eed\u4fdd\u6301\u6bcf\u65e510000\u6b65\u4ee5\u4e0a\u7684\u9ad8\u6b65\u6570\uff0c\u5e76\u575a\u6301\u722c\u697c\u68af\uff0c\u8fd9\u6709\u52a9\u4e8e\u7ef4\u6301\u8f83\u9ad8\u7684\u603b\u80fd\u91cf\u6d88\u8017\u3002", "**\u67d4\u97e7\u6027\u4e0e\u653e\u677e**\uff1a\u6bcf\u5468\u8fdb\u884c2-3\u6b21\u62c9\u4f38\u6216\u6ce1\u6cab\u8f74\u653e\u677e\uff0c\u6bcf\u6b2110-15\u5206\u949f\uff0c\u4fc3\u8fdb\u808c\u8089\u6062\u590d\uff0c\u9884\u9632\u635f\u4f24\u3002"]}, "potentialRisks": ["**\u8fc7\u5feb\u7684\u51cf\u91cd\u901f\u5ea6**\uff1a\u5728\u77ed\u77ed22\u5929\u5185\u51cf\u91cd10.25\u516c\u65a4\uff0c\u5e73\u5747\u6bcf\u5468\u8d85\u8fc73\u516c\u65a4\uff0c\u8fdc\u8d85\u5b89\u5168\u63a8\u8350\u503c\uff080.5-1\u516c\u65a4/\u5468\uff09\u3002\u5982\u6b64\u5feb\u901f\u7684\u51cf\u91cd\u53ef\u80fd\u5bfc\u81f4\u808c\u8089\u6d41\u5931\u8fc7\u591a\u3001\u57fa\u7840\u4ee3\u8c22\u7387\u4e0b\u964d\u3001\u76ae\u80a4\u677e\u5f1b\u4ee5\u53ca\u6f5c\u5728\u7684\u8425\u517b\u4e0d\u826f\u3002", "**\u65e9\u671f\u8425\u517b\u6570\u636e\u7f3a\u5931\u4e0e\u540e\u671f\u70ed\u91cf\u6444\u5165\u4e0d\u8db3**\uff1a\u524d9\u5929\u7f3a\u4e4f\u8be6\u7ec6\u7684\u996e\u98df\u6570\u636e\uff0c\u65e0\u6cd5\u5224\u65ad\u662f\u5426\u5b58\u5728\u8425\u517b\u5931\u8861\u3002\u800c\u5728\u6709\u8bb0\u5f55\u7684\u540e\u534a\u7a0b\uff0c\u6709\u6570\u65e5\u70ed\u91cf\u6444\u5165\u8fc7\u4f4e\uff08\u59828\u670817\u65e5\u4ec5935\u5927\u5361\uff09\uff0c\u8fd9\u53ef\u80fd\u5f15\u53d1\u8eab\u4f53\u7684\u4fdd\u62a4\u6027\u53cd\u5e94\uff0c\u5bfc\u81f4\u4ee3\u8c22\u653e\u7f13\uff0c\u5e76\u589e\u52a0\u540e\u671f\u66b4\u996e\u66b4\u98df\u7684\u98ce\u9669\u3002", "**\u7761\u7720\u4e0d\u8db3\u5bf9\u51cf\u8102\u7684\u5f71\u54cd**\uff1a8\u670818\u65e5\u4ec55.5\u5c0f\u65f6\u7684\u7761\u7720\u65f6\u957f\u662f\u4e2a\u8b66\u793a\u3002\u957f\u671f\u7761\u7720\u4e0d\u8db3\u4f1a\u6270\u4e71\u7626\u7d20\u548c\u9965\u997f\u7d20\u7b49\u98df\u6b32\u8c03\u8282\u6fc0\u7d20\uff0c\u589e\u52a0\u5bf9\u9ad8\u70ed\u91cf\u98df\u7269\u7684\u6e34\u671b\uff0c\u540c\u65f6\u5f71\u54cd\u8eab\u4f53\u6062\u590d\u548c\u808c\u8089\u5408\u6210\uff0c\u6700\u7ec8\u963b\u788d\u51cf\u8102\u8fdb\u7a0b\u3002"], "weeklyOutlook": "\u606d\u559c\u60a8\u5728\u8fc7\u53bb\u4e09\u5468\u53d6\u5f97\u4e86\u60ca\u4eba\u7684\u51cf\u91cd\u6210\u679c\uff0c\u5c55\u73b0\u4e86\u5f3a\u5927\u7684\u6267\u884c\u529b\u3002\u7136\u800c\uff0c\u4e3a\u4e86\u786e\u4fdd\u5065\u5eb7\u548c\u53ef\u6301\u7eed\u53d1\u5c55\uff0c\u4e0b\u4e00\u5468\u7684\u7126\u70b9\u5c06\u662f\uff1a\u7a33\u5b9a\u70ed\u91cf\u6444\u5165\uff0c\u907f\u514d\u6781\u7aef\u4f4e\u5361\uff0c\u5e76\u4e25\u683c\u4fdd\u969c7.5\u5c0f\u65f6\u4ee5\u4e0a\u7684\u4f18\u8d28\u7761\u7720\u3002\u6211\u4eec\u5c06\u4ece''\u901f\u5ea6''\u8f6c\u5411''\u8d28\u91cf''\uff0c\u4e3a\u66f4\u957f\u8fdc\u7684\u5065\u5eb7\u76ee\u6807\u5960\u5b9a\u575a\u5b9e\u57fa\u7840\u3002"}','2025-08-22 03:35:39');
INSERT INTO analysis_reports VALUES(7,2,'{"progressScore": 75, "keyMetrics": {"totalWeightLoss": 10.25, "totalWaistReduction": -1.0, "avgWeeklyLoss": 3.42, "avgCalorieDeficit": 1312.2, "avgActivityExpenditure": 400.0}, "consistency": {"logStreak": 2, "consistencyPercentage": 100.0}, "weeklySummary": [{"week": "2025-08-01 \u81f3 2025-08-07", "avgWeight": 108.24, "weightChange": -4.15}, {"week": "2025-08-08 \u81f3 2025-08-14", "avgWeight": 103.72, "weightChange": -3.83}, {"week": "2025-08-15 \u81f3 2025-08-22", "avgWeight": 103.38, "weightChange": -1.07}], "sleepAnalysis": {"avgHours": 7.54, "correlationComment": "\u5e73\u5747\u7761\u7720\u65f6\u957f\u4e3a7.54\u5c0f\u65f6\uff0c\u5c5e\u4e8e\u5065\u5eb7\u8303\u56f4\u3002\u867d\u7136\u90e8\u5206\u65e5\u671f\uff088\u670818\u65e5\uff09\u7761\u7720\u65f6\u95f4\u504f\u77ed\uff0c\u4f46\u603b\u4f53\u5bf9\u51cf\u91cd\u8d8b\u52bf\u672a\u4ea7\u751f\u660e\u663e\u8d1f\u9762\u5f71\u54cd\u3002\u5efa\u8bae\u7ee7\u7eed\u4fdd\u6301\u89c4\u5f8b\u7684\u7761\u7720\u65f6\u95f4\uff0c\u4ee5\u652f\u6301\u8eab\u4f53\u6062\u590d\u548c\u65b0\u9648\u4ee3\u8c22\u3002"}, "hydrationAnalysis": {"avgWaterL": 2.32, "comment": "\u5e73\u5747\u6bcf\u65e5\u996e\u6c342.32\u5347\uff0c\u7565\u9ad8\u4e8e\u5927\u591a\u6570\u63a8\u8350\u91cf\uff082-2.5\u5347\uff09\uff0c\u5bf9\u4e8e\u60a8\u7684\u6d3b\u52a8\u6c34\u5e73\u548c\u4f53\u91cd\u662f\u5145\u8db3\u7684\u3002\u8bf7\u7ee7\u7eed\u4fdd\u6301\uff0c\u5c24\u5176\u5728\u8fd0\u52a8\u540e\u53ca\u65f6\u8865\u5145\u6c34\u5206\u3002"}, "nutritionInsights": {"overall": "\u60a8\u7684\u996e\u98df\u8bb0\u5f55\u663e\u793a\u51fa\u79ef\u6781\u7684\u53d8\u5316\uff0c\u86cb\u767d\u8d28\u6444\u5165\u91cf\u5728\u5927\u90e8\u5206\u65f6\u95f4\u5f97\u5230\u4fdd\u969c\uff0c\u5c24\u5176\u662f\u6700\u8fd1\u51e0\u5929\u3002\u4f46\u603b\u70ed\u91cf\u6444\u5165\u5728\u90e8\u5206\u65e5\u5b50\u504f\u4f4e\uff08\u4f4e\u4e8e1200\u5927\u5361\uff09\uff0c\u5b58\u5728\u4e0d\u7a33\u5b9a\u6027\u3002\u9700\u8981\u6ce8\u610f\u7684\u662f\uff0c\u90e8\u5206\u9910\u6b21\u7684\u5b8f\u91cf\u8425\u517b\u7d20\u5206\u914d\uff0c\u5c24\u5176\u662f\u78b3\u6c34\u5316\u5408\u7269\u548c\u8102\u80aa\uff0c\u5b58\u5728\u6ce2\u52a8\uff0c\u9700\u8981\u66f4\u7cbe\u7ec6\u5316\u7684\u7ba1\u7406\u3002", "positive": "\u86cb\u767d\u8d28\u6444\u5165\u91cf\u5728\u8fd1\u671f\u6709\u663e\u8457\u63d0\u5347\uff0c\u5e76\u57fa\u672c\u7ef4\u6301\u5728\u8f83\u9ad8\u6c34\u5e73\uff08\u5e73\u5747\u7ea690\u514b/\u5929\uff09\uff0c\u8fd9\u5bf9\u4e8e\u4f53\u91cd\u7ba1\u7406\u548c\u808c\u8089\u7ef4\u6301\u81f3\u5173\u91cd\u8981\u3002\u8fd0\u52a8\u91cf\u4e5f\u666e\u904d\u53ef\u89c2\uff0c\u591a\u6570\u65e5\u5b50\u6b65\u6570\u8fc7\u4e07\u3002", "improvement": "\u9700\u8981\u4f18\u5316\u7684\u662f\uff1a1. \u589e\u52a0\u996e\u98df\u7684\u6574\u4f53\u70ed\u91cf\u6444\u5165\u7a33\u5b9a\u6027\uff0c\u907f\u514d\u8fc7\u4f4e\u7684\u6444\u5165\u65e5\u30022. \u63d0\u9ad8\u78b3\u6c34\u5316\u5408\u7269\u548c\u5065\u5eb7\u8102\u80aa\u7684\u6444\u5165\u6bd4\u4f8b\uff0c\u786e\u4fdd\u8eab\u4f53\u6709\u8db3\u591f\u7684\u80fd\u91cf\u4f9b\u5e94\u30023. \u589e\u52a0\u81b3\u98df\u7ea4\u7ef4\u548c\u5fae\u91cf\u8425\u517b\u7d20\u7684\u6444\u5165\uff0c\u4f8b\u5982\u901a\u8fc7\u589e\u52a0\u852c\u83dc\u548c\u6c34\u679c\u7684\u79cd\u7c7b\u548c\u4efd\u91cf\u3002", "macroDistribution": {"proteinPercentage": 25.9, "carbsPercentage": 44.6, "fatPercentage": 29.5, "comment": "\u5b8f\u91cf\u8425\u517b\u7d20\u5206\u914d\u4e2d\uff0c\u86cb\u767d\u8d28\u6bd4\u4f8b\uff0825.9%\uff09\u5c1a\u53ef\uff0c\u4f46\u78b3\u6c34\u5316\u5408\u7269\uff0844.6%\uff09\u548c\u8102\u80aa\uff0829.5%\uff09\u7684\u6bd4\u4f8b\u9700\u8981\u6839\u636e\u60a8\u7684\u603b\u70ed\u91cf\u76ee\u6807\u8fdb\u884c\u8c03\u6574\u3002\u4f8b\u5982\uff0c\u5f53\u603b\u70ed\u91cf\u6444\u5165\u8f83\u4f4e\u65f6\uff0c\u78b3\u6c34\u5316\u5408\u7269\u7684\u6bd4\u4f8b\u53ef\u80fd\u663e\u5f97\u504f\u9ad8\u3002\u5efa\u8bae\u5728\u603b\u70ed\u91cf\u5145\u8db3\u7684\u60c5\u51b5\u4e0b\uff0c\u4fdd\u6301\u86cb\u767d\u8d28\u5360\u603b\u80fd\u91cf\u768430-35%\uff0c\u78b3\u6c34\u5316\u5408\u7269\u536040-50%\uff0c\u5065\u5eb7\u8102\u80aa\u536020-30%\u3002"}}, "achievements": ["\u5728\u7ea63\u5468\u7684\u65f6\u95f4\u5185\u6210\u529f\u51cf\u91cd10.25\u516c\u65a4\uff0c\u4f53\u91cd\u4ece112.35\u516c\u65a4\u964d\u81f3102.1\u516c\u65a4\u3002", "\u8170\u56f4\u51cf\u5c111.0\u5398\u7c73\uff0c\u663e\u793a\u51fa\u8102\u80aa\u51cf\u5c11\u7684\u79ef\u6781\u8d8b\u52bf\u3002", "\u5e73\u5747\u6bcf\u5468\u51cf\u91cd3.42\u516c\u65a4\uff0c\u5c5e\u4e8e\u5065\u5eb7\u4e14\u53ef\u6301\u7eed\u7684\u51cf\u91cd\u901f\u5ea6\u3002", "\u6bcf\u65e5\u65e5\u5fd7\u8bb0\u5f55\u7684\u5b8c\u6574\u6027\uff0822\u5929\u8fde\u7eed\u8bb0\u5f55\uff09\u548c\u8fd0\u52a8\u4e60\u60ef\uff08\u6b65\u6570\u8fc7\u4e07\u3001\u722c\u697c\uff09\u7684\u575a\u6301\u503c\u5f97\u80af\u5b9a\u3002"], "actionableTips": ["**\u4f18\u5316\u65e9\u9910\u6784\u6210**: \u9274\u4e8e\u60a8\u5e38\u6444\u5165\u7684\u9e21\u86cb\u3001\u725b\u5976\u3001\u5168\u9ea6\u9762\u5305\u3001\u7389\u7c73\u7b49\uff0c\u53ef\u4ee5\u8003\u8651\u589e\u52a0\u4e00\u4efd\u5bcc\u542b\u81b3\u98df\u7ea4\u7ef4\u7684\u852c\u83dc\uff08\u5982\u83e0\u83dc\u3001\u756a\u8304\uff09\uff0c\u6216\u5c11\u91cf\u575a\u679c\uff0c\u4ee5\u63d0\u9ad8\u9971\u8179\u611f\u548c\u5fae\u91cf\u5143\u7d20\u6444\u5165\u3002", "**\u589e\u52a0\u9910\u98df\u7684\u5065\u5eb7\u8102\u80aa**: \u5728\u70f9\u996a\u65f6\u9002\u91cf\u4f7f\u7528\u6a44\u6984\u6cb9\u3001\u725b\u6cb9\u679c\u6cb9\uff0c\u6216\u5728\u6c99\u62c9\u4e2d\u52a0\u5165\u5c11\u91cf\u725b\u6cb9\u679c\u3001\u575a\u679c\uff0c\u4ee5\u6ee1\u8db3\u8eab\u4f53\u5bf9\u5fc5\u9700\u8102\u80aa\u9178\u7684\u9700\u6c42\uff0c\u5e76\u63d0\u5347\u9971\u8179\u611f\u3002", "**\u63a7\u5236\u78b3\u6c34\u5316\u5408\u7269\u7684\u7cbe\u52a0\u5de5\u7a0b\u5ea6**: \u4f18\u5148\u9009\u62e9\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff0c\u5982\u7cd9\u7c73\u3001\u85dc\u9ea6\u3001\u5168\u9ea6\u5236\u54c1\u3001\u85af\u7c7b\uff0c\u51cf\u5c11\u7cbe\u5236\u8c37\u7269\u7684\u6444\u5165\u3002", "**\u665a\u9910\u70ed