b58\u5728\u90e8\u5206\u65e5\u671f\u70ed\u91cf\u6444\u5165\u504f\u4f4e\uff0c\u800c\u53e6\u4e00\u4e9b\u65e5\u671f\u6444\u5165\u91cf\u9002\u4e2d\u3002\u86cb\u767d\u8d28\u6444\u5165\u666e\u904d\u504f\u9ad8\uff08\u5e73\u5747\u7ea685\u514b\uff09\uff0c\u8fd9\u5bf9\u4e8e\u808c\u8089\u7ef4\u6301\u6709\u76ca\uff0c\u4f46\u6709\u65f6\u4f1a\u4ee5\u78b3\u6c34\u5316\u5408\u7269\u6216\u8102\u80aa\u7684\u964d\u4f4e\u4e3a\u4ee3\u4ef7\u3002\u6c34\u679c\u548c\u852c\u83dc\u7684\u6444\u5165\u91cf\u672a\u660e\u786e\u91cf\u5316\uff0c\u4f46\u901a\u8fc7\u9910\u98df\u63cf\u8ff0\u53ef\u4ee5\u63a8\u65ad\u5176\u5b58\u5728\u3002", "positive": "\u60a8\u7684\u86cb\u767d\u8d28\u6444\u5165\u91cf\u666e\u904d\u8f83\u9ad8\uff0c\u8fd9\u5bf9\u4e8e100\u516c\u65a4\u4ee5\u4e0a\u7684\u4f53\u91cd\u4ee5\u53ca\u51cf\u91cd\u8fc7\u7a0b\u4e2d\u7684\u808c\u8089\u7ef4\u6301\u81f3\u5173\u91cd\u8981\u3002\u591a\u9910\u6b21\u3001\u7ed3\u6784\u6e05\u6670\u7684\u996e\u98df\u8bb0\u5f55\u8868\u660e\u60a8\u5bf9\u996e\u98df\u7ba1\u7406\u6709\u4e00\u5b9a\u8ba4\u77e5\u3002\u5927\u90e8\u5206\u9910\u98df\u9009\u62e9\u84b8\u3001\u716e\u3001\u51c9\u62cc\u7b49\u4f4e\u6cb9\u70f9\u996a\u65b9\u5f0f\uff0c\u8fd9\u662f\u79ef\u6781\u7684\u3002", "improvement": "\u5b58\u5728\u90e8\u5206\u65e5\u671f\u70ed\u91cf\u6444\u5165\uff08\u59828\u67082\u65e5600kcal\uff0c8\u670817\u65e5935kcal\uff09\u4e25\u91cd\u504f\u4f4e\uff0c\u8fd9\u53ef\u80fd\u5bfc\u81f4\u808c\u8089\u6d41\u5931\u548c\u65b0\u9648\u4ee3\u8c22\u7d0a\u4e71\u3002\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u91cf\u5728\u90e8\u5206\u65e5\u671f\uff08\u59828\u670812\u65e5200g\uff09\u504f\u9ad8\uff0c\u800c\u8102\u80aa\u6444\u5165\u5728\u5176\u4ed6\u65e5\u671f\uff08\u59828\u670812\u65e545g\uff09\u7565\u663e\u4e0d\u8db3\u3002\u5fae\u91cf\u8425\u517b\u7d20\uff08\u5982\u7ea4\u7ef4\u3001\u7ef4\u751f\u7d20\uff09\u7684\u6444\u5165\u91cf\u672a\u8be6\u7ec6\u8bc4\u4f30\uff0c\u9700\u5173\u6ce8\u591a\u6837\u6027\u3002", "macroDistribution": {"proteinPercentage": 31.0, "carbsPercentage": 44.0, "fatPercentage": 25.0, "comment": "\u5b8f\u91cf\u8425\u517b\u7d20\u5e73\u5747\u5206\u5e03\u7ea6\u4e3a\u86cb\u767d\u8d2831%\uff0c\u78b3\u6c34\u5316\u5408\u726944%\uff0c\u8102\u80aa25%\u3002\u86cb\u767d\u8d28\u6bd4\u4f8b\u5065\u5eb7\uff0c\u8102\u80aa\u6bd4\u4f8b\u5904\u4e8e\u5408\u7406\u8303\u56f4\uff0c\u78b3\u6c34\u5316\u5408\u7269\u5360\u6bd4\u7565\u9ad8\u3002\u5728\u51cf\u91cd\u521d\u671f\uff0c\u5efa\u8bae\u5c06\u78b3\u6c34\u5316\u5408\u7269\u6bd4\u4f8b\u7a0d\u5fae\u964d\u4f4e\uff0c\u540c\u65f6\u589e\u52a0\u5065\u5eb7\u8102\u80aa\u7684\u6444\u5165\uff0c\u4ee5\u63d0\u5347\u9971\u8179\u611f\u548c\u652f\u6301\u6fc0\u7d20\u5e73\u8861\u3002"}}, "achievements": ["\u572822\u5929\u5185\u6210\u529f\u51cf\u91cd10.25\u516c\u65a4\uff0c\u5e73\u5747\u6bcf\u5468\u51cf\u91cd2.56\u516c\u65a4\uff0c\u901f\u5ea6\u663e\u8457\u3002", "\u8170\u56f4\u51cf\u5c113.0\u5398\u7c73\uff0c\u663e\u793a\u8eab\u4f53\u56f4\u5ea6\u6709\u6240\u6539\u5584\u3002", "\u5927\u90e8\u5206\u65e5\u671f\u5747\u4fdd\u6301\u4e86\u8f83\u9ad8\u7684\u86cb\u767d\u8d28\u6444\u5165\u91cf\uff0c\u6709\u5229\u4e8e\u808c\u8089\u7ef4\u6301\u3002", "\u8fd0\u52a8\u8bb0\u5f55\u663e\u793a\u6301\u7eed\u7684\u65e5\u5e38\u6d3b\u52a8\uff08\u6b65\u6570\u3001\u722c\u697c\uff09\uff0c\u5bf9\u6574\u4f53\u5065\u5eb7\u6709\u76ca\u3002"], "actionableTips": ["**\u7a33\u5b9a\u70ed\u91cf\u6444\u5165**: \u907f\u514d\u6781\u7aef\u4f4e\u70ed\u91cf\u65e5\uff08\u5982600kcal, 935kcal\uff09\uff0c\u76ee\u6807\u70ed\u91cf\u6444\u5165\u5e94\u57281200-1500kcal\u4e4b\u95f4\uff0c\u5e76\u4fdd\u6301\u76f8\u5bf9\u7a33\u5b9a\uff0c\u4ee5\u652f\u6301\u6301\u7eed\u7684\u4f53\u91cd\u4e0b\u964d\u548c\u8eab\u4f53\u529f\u80fd\u3002", "**\u4f18\u5316\u5b8f\u91cf\u8425\u517b\u7d20**: \u5c1d\u8bd5\u5c06\u78b3\u6c34\u5316\u5408\u7269\u6bd4\u4f8b\u5fae\u8c03\u81f335-40%\uff0c\u540c\u65f6\u589e\u52a0\u5065\u5eb7\u8102\u80aa\uff08\u5982\u575a\u679c\u3001\u725b\u6cb9\u679c\u3001\u6a44\u6984\u6cb9\uff09\u7684\u6444\u5165\u81f325-30%\uff0c\u4ee5\u63d0\u5347\u9971\u8179\u611f\u5e76\u63d0\u4f9b\u5fc5\u9700\u8102\u80aa\u9178\u3002", "**\u589e\u52a0\u852c\u83dc\u548c\u6c34\u679c\u6444\u5165**: \u5728\u6bcf\u9910\u4e2d\u4f18\u5148\u589e\u52a0\u975e\u6dc0\u7c89\u7c7b\u852c\u83dc\u7684\u4efd\u91cf\uff0c\u786e\u4fdd\u6444\u5165\u8db3\u591f\u7684\u81b3\u98df\u7ea4\u7ef4\u3001\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\u3002", "**\u4fdd\u8bc1\u5145\u8db3\u7761\u7720**: \u52aa\u529b\u5c06\u7761\u7720\u65f6\u95f4\u7a33\u5b9a\u57287-8\u5c0f\u65f6\uff0c\u8fd9\u5bf9\u4e8e\u4f53\u91cd\u7ba1\u7406\u3001\u60c5\u7eea\u7a33\u5b9a\u548c\u8eab\u4f53\u6062\u590d\u81f3\u5173\u91cd\u8981\u3002", "**\u7cbe\u51c6\u8bb0\u5f55**: \u5c3d\u91cf\u51c6\u786e\u8bb0\u5f55\u6bcf\u9910\u7684\u98df\u6750\u548c\u4efd\u91cf\uff0c\u5c24\u5176\u6ce8\u610f\u70f9\u996a\u7528\u6cb9\u91cf\uff0c\u4ee5\u4fbf\u66f4\u51c6\u786e\u5730\u8bc4\u4f30\u70ed\u91cf\u548c\u5b8f\u91cf\u8425\u517b\u7d20\u6444\u5165\u3002"], "recommendedSuperfoods": [{"food": "\u725b\u6cb9\u679c", "reason": "\u63d0\u4f9b\u5065\u5eb7\u7684\u5355\u4e0d\u9971\u548c\u8102\u80aa\u9178\uff0c\u6709\u52a9\u4e8e\u63d0\u9ad8\u9971\u8179\u611f\uff0c\u5ef6\u7f13\u80c3\u6392\u7a7a\uff0c\u5e76\u63d0\u4f9b\u7ef4\u751f\u7d20E\u548c\u94be\u3002\u53ef\u4ee5\u4f5c\u4e3a\u65e9\u9910\u6216\u6c99\u62c9\u7684\u8865\u5145\u3002"}, {"food": "\u575a\u679c\uff08\u5982\u674f\u4ec1\u3001\u6838\u6843\uff09", "reason": "\u5bcc\u542b\u5065\u5eb7\u8102\u80aa\u3001\u86cb\u767d\u8d28\u3001\u7ea4\u7ef4\u548c\u591a\u79cd\u7ef4\u751f\u7d20\u77ff\u7269\u8d28\u3002\u4f5c\u4e3a\u52a0\u9910\u6216\u6dfb\u52a0\u5230\u6c99\u62c9\u4e2d\uff0c\u80fd\u663e\u8457\u63d0\u5347\u9971\u8179\u611f\u548c\u8425\u517b\u5bc6\u5ea6\u3002"}, {"food": "\u7eff\u53f6\u852c\u83dc\uff08\u5982\u83e0\u83dc\u3001\u7fbd\u8863\u7518\u84dd\uff09", "reason": "\u70ed\u91cf\u6781\u4f4e\uff0c\u4f46\u5bcc\u542b\u7ef4\u751f\u7d20A\u3001C\u3001K\u3001\u53f6\u9178\u3001\u94c1\u548c\u81b3\u98df\u7ea4\u7ef4\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\uff0c\u4fc3\u8fdb\u80a0\u9053\u5065\u5eb7\uff0c\u5e76\u63d0\u4f9b\u6297\u6c27\u5316\u5242\u3002"}, {"food": "\u4e09\u6587\u9c7c", "reason": "\u5bcc\u542b\u4f18\u8d28\u86cb\u767d\u8d28\u548cOmega-3\u8102\u80aa\u9178\uff0c\u5bf9\u5fc3\u8840\u7ba1\u5065\u5eb7\u3001\u5927\u8111\u529f\u80fd\u4ee5\u53ca\u6297\u708e\u6709\u76ca\u3002\u591a\u6b21\u51fa\u73b0\u5728\u60a8\u7684\u5348\u9910\u8bb0\u5f55\u4e2d\uff0c\u5e94\u7ee7\u7eed\u4fdd\u6301\u3002"}, {"food": "\u85dc\u9ea6", "reason": "\u4e00\u79cd\u5168\u8c37\u7269\uff0c\u86cb\u767d\u8d28\u542b\u91cf\u9ad8\u4e8e\u5927\u591a\u6570\u8c37\u7269\uff0c\u5bcc\u542b\u81b3\u98df\u7ea4\u7ef4\u3001\u591a\u79cd\u77ff\u7269\u8d28\u548c\u6297\u6c27\u5316\u5242\u3002\u53ef\u4ee5\u66ff\u4ee3\u90e8\u5206\u767d\u7c73\u996d\uff0c\u63d0\u4f9b\u66f4\u6301\u4e45\u7684\u80fd\u91cf\u3002"}], "exercisePrescription": {"recommendation": "\u9274\u4e8e\u60a8\u76ee\u524d\u79ef\u6781\u7684\u8fd0\u52a8\u4e60\u60ef\uff0c\u5efa\u8bae\u5728\u4fdd\u6301\u73b0\u6709\u65e5\u5e38\u6d3b\u52a8\uff08\u6b65\u6570\u3001\u722c\u697c\uff09\u7684\u57fa\u7840\u4e0a\uff0c\u8fdb\u4e00\u6b65\u589e\u52a0\u529b\u91cf\u8bad\u7ec3\u7684\u9891\u7387\u548c\u5f3a\u5ea6\uff0c\u5e76\u5c06\u6709\u6c27\u8fd0\u52a8\uff08\u5982\u9a91\u884c\u3001\u5feb\u8d70+\u6162\u8dd1\uff09\u7eb3\u5165\u6bcf\u54683-4\u6b21\uff0c\u6bcf\u6b2130-45\u5206\u949f\u7684\u8ba1\u5212\u3002", "details": ["**\u529b\u91cf\u8bad\u7ec3**: \u6bcf\u54683\u6b21\uff0c\u6bcf\u6b2145-60\u5206\u949f\uff0c\u91cd\u70b9\u5173\u6ce8\u590d\u5408\u52a8\u4f5c\uff08\u5982\u6df1\u8e72\u3001\u786c\u62c9\u3001\u5367\u63a8\u3001\u5212\u8239\u3001\u80a9\u63a8\uff09\uff0c\u65e8\u5728\u589e\u52a0\u808c\u8089\u91cf\uff0c\u63d0\u5347\u57fa\u7840\u4ee3\u8c22\u3002", "**\u6709\u6c27\u8fd0\u52a8**: \u6bcf\u54683-4\u6b21\uff0c\u6bcf\u6b2130-45\u5206\u949f\uff0c\u53ef\u9009\u62e9\u5feb\u8d70\u3001\u6162\u8dd1\u3001\u6e38\u6cf3\u6216\u9a91\u884c\u3002\u53ef\u8003\u8651\u52a0\u5165\u9ad8\u5f3a\u5ea6\u95f4\u6b47\u8bad\u7ec3\uff08HIIT\uff091-2\u6b21\uff0c\u4ee5\u63d0\u9ad8\u71c3\u8102\u6548\u7