INSERT INTO analysis_reports VALUES(9,2,'{"progressScore": 85, "keyMetrics": {"totalWeightLoss": 10.25, "totalWaistReduction": 3.0, "avgWeeklyLoss": 3.26, "avgCalorieDeficit": 1171.74, "avgActivityExpenditure": 461.0}, "consistency": {"logStreak": 22, "consistencyPercentage": 100.0}, "weeklySummary": [{"week": "1", "avgWeight": 111.23, "weightChange": -1.12}, {"week": "2", "avgWeight": 108.63, "weightChange": -2.6}, {"week": "3", "avgWeight": 104.98, "weightChange": -3.65}, {"week": "3.14", "avgWeight": 103.8, "weightChange": -1.18}], "sleepAnalysis": {"avgHours": 7.54, "correlationComment": "\u60a8\u7684\u5e73\u5747\u7761\u7720\u65f6\u95f4\u57287-8\u5c0f\u65f6\u4e4b\u95f4\uff0c\u8fd9\u5bf9\u4e8e\u8eab\u4f53\u6062\u590d\u548c\u4f53\u91cd\u7ba1\u7406\u662f\u8f83\u4e3a\u7406\u60f3\u7684\u3002\u5c3d\u7ba1\u57282025-08-18\u51fa\u73b0\u4e865.5\u5c0f\u65f6\u7684\u7761\u7720\uff0c\u6574\u4f53\u5f71\u54cd\u5c1a\u4e0d\u663e\u8457\uff0c\u4f46\u957f\u671f\u7761\u7720\u4e0d\u8db3\u4ecd\u53ef\u80fd\u5f71\u54cd\u65b0\u9648\u4ee3\u8c22\u548c\u98df\u6b32\u63a7\u5236\u3002"}, "hydrationAnalysis": {"avgWaterL": 2.26, "comment": "\u60a8\u7684\u5e73\u5747\u996e\u6c34\u91cf\u7ea6\u4e3a2.26\u5347\uff0c\u63a5\u8fd1\u63a8\u8350\u91cf\u3002\u5728\u4f53\u91cd\u8f83\u9ad8\u7684\u60c5\u51b5\u4e0b\uff0c\u4fdd\u6301\u5145\u8db3\u7684\u6c34\u5206\u5bf9\u4e8e\u652f\u6301\u65b0\u9648\u4ee3\u8c22\u548c\u63a7\u5236\u98df\u6b32\u81f3\u5173\u91cd\u8981\u3002\u8bf7\u6ce8\u610f\u5728\u8fd0\u52a8\u91cf\u8f83\u5927\u7684\u65e5\u5b50\u6216\u5929\u6c14\u708e\u70ed\u65f6\u9002\u91cf\u589e\u52a0\u996e\u6c34\u3002"}, "nutritionInsights": {"overall": "\u60a8\u7684\u996e\u98df\u6444\u5165\u91cf\u5728\u5927\u591a\u6570\u65e5\u5b50\u91cc\u662f\u53ef\u63a7\u7684\uff0c\u5e76\u4e14\u5728\u5468\u5ea6\u5e73\u5747\u503c\u4e0a\u4fdd\u6301\u4e86\u663e\u8457\u7684\u70ed\u91cf\u8d64\u5b57\u3002\u6574\u4f53\u5b8f\u91cf\u8425\u517b\u7d20\u6bd4\u4f8b\u5728\u540e\u671f\u8d8b\u4e8e\u7a33\u5b9a\uff0c\u86cb\u767d\u8d28\u6444\u5165\u91cf\u5728\u591a\u6570\u65e5\u5b50\u91cc\u8868\u73b0\u4e0d\u9519\uff0c\u5c24\u5176\u57288\u670818\u65e5\u8fbe\u5230\u4e86\u5cf0\u503c\u3002", "positive": "\u60a8\u5728\u5927\u90e8\u5206\u8bb0\u5f55\u65e5\u4fdd\u6301\u4e86\u8f83\u9ad8\u7684\u86cb\u767d\u8d28\u6444\u5165\uff08\u5e73\u5747\u7ea677\u514b\uff09\uff0c\u8fd9\u5bf9\u4e8e\u4f53\u91cd100\u516c\u65a4\u4ee5\u4e0a\u7684\u4e2a\u4f53\u6765\u8bf4\uff0c\u5728\u51cf\u91cd\u8fc7\u7a0b\u4e2d\u652f\u6301\u808c\u8089\u7ef4\u6301\u81f3\u5173\u91cd\u8981\u3002\u8fd0\u52a8\u6d88\u8017\u548c\u70ed\u91cf\u6444\u5165\u63a7\u5236\u4e5f\u4f53\u73b0\u4e86\u60a8\u79ef\u6781\u7684\u6001\u5ea6\u3002", "improvement": "\u65e9\u671f\uff088\u67081\u65e5\u81f38\u67087\u65e5\uff09\u7684\u996e\u98df\u5206\u6790\u663e\u793a\uff0c\u90e8\u5206\u9910\u98df\u7684\u86cb\u767d\u8d28\u6444\u5165\u76f8\u5bf9\u4e0d\u8db3\uff08\u4f8b\u59828\u67082\u65e5\u86cb\u767d\u8d28\u4ec518\u514b\uff09\uff0c\u867d\u7136\u70ed\u91cf\u6444\u5165\u4e5f\u8f83\u4f4e\uff0c\u4f46\u8fd9\u79cd\u4e0d\u5747\u8861\u53ef\u80fd\u5bfc\u81f4\u808c\u8089\u6d41\u5931\u3002\u540e\u671f\u996e\u98df\u7ed3\u6784\u6709\u6539\u5584\uff0c\u4f46\u4ecd\u9700\u5173\u6ce8\u78b3\u6c34\u5316\u5408\u7269\u7684\u6765\u6e90\u548c\u603b\u91cf\uff0c\u5e76\u786e\u4fdd\u5065\u5eb7\u8102\u80aa\u7684\u5145\u8db3\u6444\u5165\u3002", "macroDistribution": {"proteinPercentage": 32.0, "carbsPercentage": 36.0, "fatPercentage": 32.0, "comment": "\u57fa\u4e8e22\u5929\u8bb0\u5f55\u7684\u5e73\u5747\u5b8f\u91cf\u8425\u517b\u7d20\u6bd4\u4f8b\uff0c\u86cb\u767d\u8d28\u5360\u603b\u70ed\u91cf\u768432%\uff0c\u78b3\u6c34\u5316\u5408\u7269\u536036%\uff0c\u8102\u80aa\u536032%\u3002\u8fd9\u4e2a\u6bd4\u4f8b\u5728\u51cf\u91cd\u671f\u95f4\u662f\u53ef\u63a5\u53d7\u7684\uff0c\u4f46\u86cb\u767d\u8d28\u6bd4\u4f8b\u53ef\u4ee5\u8fdb\u4e00\u6b65\u63d0\u9ad8\uff0c\u4ee5\u66f4\u597d\u5730\u652f\u6301\u808c\u8089\u7ef4\u6301\u548c\u9971\u8179\u611f\uff0c\u540c\u65f6\u6ce8\u610f\u78b3\u6c34\u5316\u5408\u7269\u7684\u9009\u62e9\uff08\u4f8b\u5982\u504f\u5411\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff09\u3002"}}, "achievements": ["\u572822\u5929\u5185\u6210\u529f\u51cf\u91cd10.25\u516c\u65a4\u3002", "\u8170\u56f4\u51cf\u5c11\u4e863.0\u5398\u7c73\u3002", "\u5e73\u5747\u6bcf\u5468\u51cf\u91cd3.26\u516c\u65a4\uff0c\u663e\u793a\u51fa\u9ad8\u6548\u7684\u51cf\u91cd\u901f\u5ea6\u3002", "\u5e73\u5747\u6bcf\u65e5\u70ed\u91cf\u8d64\u5b57\u9ad8\u8fbe1171.74\u5927\u5361\uff0c\u4e3a\u5feb\u901f\u51cf\u91cd\u63d0\u4f9b\u4e86\u57fa\u7840\u3002", "\u5e73\u5747\u8fd0\u52a8\u6d88\u8017\u8fbe\u5230461\u5927\u5361\uff0c\u652f\u6301\u4e86\u6574\u4f53\u80fd\u91cf\u5e73\u8861\u3002", "\u7edd\u5927\u591a\u6570\u65e5\u671f\u4fdd\u6301\u4e86\u5145\u8db3\u7684\u7761\u7720\uff08\u5e73\u57477.54\u5c0f\u65f6\uff09\u548c\u5408\u7406\u7684\u6c34\u5206\u6444\u5165\uff08\u5e73\u57472.26\u5347\uff09\u3002", "\u5728\u5927\u90e8\u5206\u8bb0\u5f55\u65e5\u4fdd\u6301\u4e86\u8f83\u9ad8\u7684\u86cb\u767d\u8d28\u6444\u5165\uff0c\u5e73\u5747\u8fbe\u523077\u514b\uff0c\u6709\u529b\u652f\u6301\u4e86\u808c\u8089\u7ef4\u6301\u3002", "\u6d3b\u52a8\u91cf\u7a33\u5b9a\uff0c\u6b65\u6570\u548c\u722c\u697c\u7684\u8bb0\u5f55\u8bc1\u660e\u4e86\u60a8\u7684\u6d3b\u8dc3\u5ea6\u3002"], "actionableTips": ["**\u4f18\u5316\u86cb\u767d\u8d28\u6444\u5165**: \u5373\u4f7f\u5728\u540e\u671f\u60a8\u7684\u86cb\u767d\u8d28\u6444\u5165\u6709\u6240\u63d0\u9ad8\uff0c\u4f46\u76ee\u6807\u5e94\u8bbe\u5b9a\u4e3a\u6bcf\u516c\u65a4\u4f53\u91cd1.6-2.2\u514b\u86cb\u767d\u8d28\uff08\u5373\u7ea6165-225\u514b\uff09\u3002\u8bf7\u4f18\u5148\u9009\u62e9\u7626\u8089\u3001\u9c7c\u7c7b\u3001\u79bd\u7c7b\u3001\u8c46\u5236\u54c1\u548c\u9e21\u86cb\u7b49\u4f18\u8d28\u86cb\u767d\u8d28\u6765\u6e90\uff0c\u5e76\u5747\u5300\u5206\u914d\u5230\u6bcf\u9910\u4e2d\u3002", "**\u7cbe\u9009\u78b3\u6c34\u5316\u5408\u7269**: \u51cf\u5c11\u7cbe\u5236\u8c37\u7269\uff08\u5982\u767d\u7c73\u996d\u3001\u767d\u9762\u5305\uff09\u7684\u6444\u5165\uff0c\u589e\u52a0\u5168\u9ea6\u3001\u7cd9\u7c73\u3001\u71d5\u9ea6\u3001\u85dc\u9ea6\u3001\u7ea2\u85af\u3001\u7389\u7c73\u7b49\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\u7684\u6bd4\u4f8b\uff0c\u5b83\u4eec\u5bcc\u542b\u81b3\u98df\u7ea4\u7ef4\uff0c\u80fd\u63d0\u4f9b\u66f4\u6301\u4e45\u7684\u9971\u8179\u611f\u5e76\u7a33\u5b9a\u8840\u7cd6\u3002", "**\u589e\u52a0\u5065\u5eb7\u8102\u80aa**: \u60a8\u7684\u8102\u80aa\u6444\u5165\u6bd4\u4f8b\u76f8\u5bf9\u5408\u7406\uff0c\u4f46\u8981\u786e\u4fdd\u8102\u80aa\u6765\u6e90\u662f\u5065\u5eb7\u7684\uff0c\u5982\u725b\u6cb9\u679c\u3001\u575a\u679c\u3001\u79cd\u5b50\u3001\u6a44\u6984\u6cb9\u548c\u5bcc\u542bomega-3\u7684\u9c7c\u7c7b\u3002\u8fd9\u4e9b\u8102\u80aa\u6709\u52a9\u4e8e\u6fc0\u7d20\u751f\u6210\u3001\u8425\u517b\u7d20\u5438\u6536\u548c\u6574\u4f53\u5065\u5eb7\u3002", "**\u5173\u6ce8\u665a\u9910\u70ed\u91cf**: 8\u670821\u65e5\u665a\u9910\u672a\u8fdb\u98df\uff0c\u867d\u7136\u603b\u4f53\u70ed\u91cf\u8d64\u5b57\u5f88\u5927\uff0c\u4f46\u957f\u671f\u665a\u9910\u4e0d\u8fdb\u98df\u53ef\u80fd\u5f71\u54cd\u591c\u95f4\u4ee3\u8c22\u548c\u8eab\u4f53\u4fee\u590d\u3002\u5efa\u8bae\u665a\u9910\u5373\u4f7f\u91cf\u5c11\uff0c\u4e5f\u5e94\u5305\u542b\u8db3\u91cf\u7684\u86cb\u767d\u8d28\u548c\u4f18\u8d28\u8102\u80aa\uff0c\u4ee5\u4fdd\u8bc1\u8425\u517b\u7684\u5b8c\u6574\u6027\u3002", "**\u7ec6\u5316\u9910\u98df\u8bb0\u5f55**: \u90e8\u5206\u9910\u98df\u7684\u8425\u517b\u6210\u5206\u4f30\u7b97\u5b58\u5728\u201c\u5206\u6790\u5931\u8d25\u201d\u6216\u4e0d\u5b8c\u6574\u7684\u60c5\u51b5\uff0c\u8fd9\u4f1a\u5f71\u54cd\u6570\u636e\u7684\u51c6\u786e\u6027\u3002\u5efa\u8bae\u5728\u8bb0\u5f55\u65f6\u5c3d\u91cf\u63d0\u4f9b\u66f4\u8be6\u7ec6\u7684\u98df\u6750\u4fe1\u606f\uff08\u5982\u4efd\u91cf\u3001\u70f9\u996a\u65b9\u5f0f\uff09\u3002"], "recommendedSuperfoods": [{"food": "\u5e0c\u814a\u9178\u5976", "reason": "\u5bcc\u542b\u9ad8\u54c1\u8d28\u86cb\u767d\u8d28\uff0c\u6bd4\u666e\u901a\u9178\u5976\u7684\u86cb\u767d\u8d28\u542b\u91cf\u66f4\u9ad8\uff0c\u6709\u52a9\u4e8e\u589e\u5f3a\u9971\u8179\u611f\uff0c\u652f\u6301\u808c\u8089\u751f\u957f\u548c\u4fee\u590d\uff0c\u540c\u65f6\u542b\u6709\u76ca\u751f\u83cc\uff0c\u6709\u76ca\u4e8e\u80a0\u9053\u5065\u5eb7\u3002"}, {"food": "\u4e09\u6587\u9c7c", "reason": "\u6781\u4f73\u7684\u86cb\u767d\u8d28\u548cOmega-3\u8102\u80aa\u9178\u6765\u6e90\uff0cOmega-3\u5177\u6709\u6297\u708e\u4f5c\u7528\uff0c\u5bf9\u5fc3\u8840\u7ba1\u5065\u5eb7\u548c\u5927\u8111\u529f\u80fd\u6709\u76ca\uff0c\u6709\u52a9\u4e8e\u8eab\u4f53\u6062\u590d\u548c\u964d\u4f4e\u6162\u6027\u75be\u75c5\u98ce\u9669\u3002"}, {"food": "\u85dc\u9ea6", "reason": "\u662f\u4e00\u79cd\u5b8c\u6574\u7684\u86cb\u767d\u8d28\u6765\u6e90\uff08\u5305\u542b\u6240\u6709\u4e5d\u79cd\u5fc5\u9700\u6c28\u57fa\u9178\uff09\uff0c\u5bcc\u542b\u81b3\u98df\u7ea4\u7ef4\u3001\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\uff0c\u662f\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\u7684\u4f18\u8d28\u9009\u62e9\uff0c\u6709\u52a9\u4e8e\u7a33\u5b9a\u8840\u7cd6\u548c\u63d0\u4f9b\u6301\u4e45\u80fd\u91cf\u3002"}, {"food": "\u7fbd\u8863\u7518\u84dd", "reason": "\u8425\u517b\u5bc6\u5ea6\u6781\u9ad8\uff0c\u5bcc\u542b\u7ef4\u751f\u7d20A\u3001C\u3001K\uff0c\u4ee5\u53ca\u9499\u3001\u94be\u548c\u6297\u6c27\u5316\u5242\u3002\u5b83\u80fd\u589e\u52a0\u81b3\u98df\u7ea4\u7ef4\u7684\u6444\u5165\uff0c\u5e2e\u52a9\u63a7\u5236\u98df\u6b32\uff0c\u4e14\u70ed\u91cf\u6781\u4f4e\u3002"}, {"food": "\u725b\u6cb9\u679c", "reason": "\u5bcc\u542b\u5355\u4e0d\u9971\u548c\u8102\u80aa\u9178\uff0c\u5bf9\u5fc3\u8840\u7ba1\u5065\u5eb7\u6709\u76ca\uff0c\u80fd\u589e\u5f3a\u9971\u8179\u611f\uff0c\u5e76\u63d0\u4f9b\u81b3\u98df\u7ea4\u7ef4\u3001\u94be\u548c\u591a\u79cd\u7ef4\u751f\u7d20\u3002\u5c06\u5176\u6dfb\u52a0\u5230\u6c99\u62c9\u6216\u4f5c\u4e3a\u96f6\u98df\uff0c\u80fd\u6709\u6548\u63d0\u9ad8\u8425\u517b\u5bc6\u5ea6\u3002"}], "exercisePrescription": {"recommendation": "\u60a8\u7684\u8fd0\u52a8\u4e60\u60ef\u5df2\u7ecf\u5efa\u7acb\uff0c\u6b65\u6570\u548c\u722c\u697c\u8bb0\u5f55\u826f\u597d\uff0c\u4f46\u529b\u91cf\u8bad\u7ec3\u7684\u9891\u7387\u548c\u5f3a\u5ea6\u9700\u8981\u660e\u786e\u548c\u52a0\u5f3a\u3002\u5efa\u8bae\u5728\u73b0\u6709\u57fa\u7840\u4e0a\uff0c\u7cfb\u7edf\u5316\u60a8\u7684\u8bad\u7ec3\uff0c\u4ee5\u6700\u5927\u5316\u51cf\u91cd\u6548\u679c\u548c\u808c\u8089\u53d1\u5c55\u3002", "details": ["**\u589e\u52a0\u529b\u91cf\u8bad\u7ec3\u9891\u7387**: \u76ee\u6807\u4e3a\u6bcf\u5468\u8fdb\u884c3-4\u6b21\u5168\u8eab\u6027\u7684\u529b\u91cf\u8bad\u7ec3\u3002\u6bcf\u6b21\u8bad\u7ec3\u4fa7\u91cd\u4e8e\u4e0d\u540c\u7684\u808c\u7fa4\uff08\u5982\u63a8\u3001\u62c9\u3001\u817f\uff09\u3002", "**\u529b\u91cf\u8bad\u7ec3\u5f3a\u5ea6**: \u9009\u62e9\u80fd\u591f\u8ba9\u60a8\u5728\u6700\u540e\u51e0\u79d2\u611f\u5230\u5403\u529b\uff088-12\u6b21\u91cd\u590d\uff09\u7684\u91cd\u91cf\u3002\u786e\u4fdd\u52a8\u4f5c\u7684\u6807\u51c6\u6027\uff0c\u907f\u514d\u53d7\u4f24\u3002", "**\u6709\u6c27\u8fd0\u52a8**: \u5728\u529b\u91cf\u8bad\u7ec3\u65e5\u6216\u72ec\u7acb\u65e5\uff0c\u4fdd\u6301\u6bcf\u54683-5\u6b21\uff0c\u6bcf\u6b2130-45\u5206\u949f\u7684\u4e2d\u9ad8\u5f3a\u5ea6\u6709\u6c27\u8fd0\u52a8\uff08\u5982\u5feb\u8d70\u3001\u6162\u8dd1\u3001\u9a91\u884c\u3001\u6e38\u6cf3\uff09\uff0c\u4ee5\u8fdb\u4e00\u6b65\u63d0\u5347\u70ed\u91cf\u6d88\u8017\u548c\u5fc3\u80ba\u529f\u80fd\u3002", "**\u6e10\u8fdb\u6027\u8d85\u8d1f\u8377**: \u968f\u7740\u4f53\u80fd\u63d0\u5347\uff0c\u9010\u6e10\u589e\u52a0\u8bad\u7ec3\u91cd\u91cf\u3001\u6b21\u6570\u6216\u7ec4\u6570\uff0c\u6216\u8005\u7f29\u77ed\u7ec4\u95f4\u4f11\u606f\u65f6\u95f4\uff0c\u6301\u7eed\u6311\u6218\u8eab\u4f53\u3002", "**\u4f11\u606f\u4e0e\u6062\u590d**: \u4fdd\u8bc1\u6bcf\u5468\u81f3\u5c111-2\u5929\u5145\u5206\u4f11\u606f\uff0c\u8ba9\u8eab\u4f53\u6709\u65f6\u95f4\u4fee\u590d\u548c\u91cd\u5efa\u808c\u8089\u3002\u5145\u8db3\u7684\u7761\u7720\uff087-8\u5c0f\u65f6\uff09\u662f\u6062\u590d\u7684\u5173\u952e\u3002"]}, "potentialRisks": ["**\u8fc7\u5feb\u7684\u51cf\u91cd\u901f\u5ea6**: \u5e73\u5747\u6bcf\u5468\u51cf\u91cd3.26\u516c\u65a4\uff0c\u867d\u7136\u6548\u679c\u663e\u8457\uff0c\u4f46\u53ef\u80fd\u7565\u5feb\u4e8e\u74