positive": "\u86cb\u767d\u8d28\u6444\u5165\u76f8\u5bf9\u5145\u8db3\uff0c\u5c24\u5176\u662f\u57288\u670818\u65e5\uff08148g\uff09\u548c8\u670813\u65e5\uff08110g\uff09\uff0c\u8fd9\u5bf9\u4e8e\u4f53\u91cd\u7ba1\u7406\u548c\u808c\u8089\u4fdd\u7559\u81f3\u5173\u91cd\u8981\u3002\u591a\u79cd\u98df\u7269\u7684\u6444\u5165\u4e5f\u4fdd\u8bc1\u4e86\u8425\u517b\u7684\u591a\u6837\u6027\u3002", "improvement": "\u90e8\u5206\u65e5\u5b50\u7684\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u504f\u9ad8\uff0c\u800c\u67d0\u4e9b\u65e5\u5b50\uff08\u59828\u670820\u65e5\uff09\u7684\u603b\u70ed\u91cf\u548c\u86cb\u767d\u8d28\u6444\u5165\u504f\u4f4e\u3002\u90e8\u5206\u65e9\u9910\u548c\u5348\u9910\u7684\u5b8f\u91cf\u8425\u517b\u7d20\u5206\u6790\u5b58\u5728\u6570\u636e\u7f3a\u5931\u6216\u4e0d\u51c6\u786e\u7684\u60c5\u51b5\u3002\u5efa\u8bae\u7ec6\u5316\u65e9\u9910\u548c\u5348\u9910\u7684\u98df\u6750\u53ca\u4efd\u91cf\uff0c\u4ee5\u786e\u4fdd\u66f4\u51c6\u786e\u7684\u8425\u517b\u8bc4\u4f30\u3002", "macroDistribution": {"proteinPercentage": 27.4, "carbsPercentage": 40.5, "fatPercentage": 32.1, "comment": "\u5e73\u5747\u5b8f\u91cf\u8425\u517b\u7d20\u5206\u914d\u4e2d\uff0c\u86cb\u767d\u8d28\u5360\u6bd4\u8f83\u9ad8\uff0c\u78b3\u6c34\u5316\u5408\u7269\u548c\u8102\u80aa\u7684\u6bd4\u4f8b\u4e5f\u5904\u4e8e\u5408\u7406\u8303\u56f4\u3002\u4f46\u9700\u6ce8\u610f\uff0c\u90e8\u5206\u65e5\u5b50\u7684\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u8fc7\u591a\uff0c\u53ef\u80fd\u9700\u8981\u9002\u5ea6\u8c03\u6574\uff0c\u589e\u52a0\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\u7684\u6bd4\u4f8b\uff0c\u5982\u7cd9\u7c73\u3001\u5168\u9ea6\u5236\u54c1\u548c\u852c\u83dc\u3002"}}, "achievements": ["\u572815\u5929\u5185\u6210\u529f\u51cf\u91cd10.25\u516c\u65a4\uff0c\u5e73\u5747\u6bcf\u5468\u51cf\u91cd3.26\u516c\u65a4\uff0c\u8fd9\u662f\u4e00\u9879\u975e\u5e38\u663e\u8457\u7684\u6210\u5c31\u3002", "\u8170\u56f4\u51cf\u5c11\u4e863.0\u5398\u7c73\uff0c\u8868\u660e\u8102\u80aa\u6574\u4f53\u51cf\u5c11\uff0c\u8179\u90e8\u8102\u80aa\u4e5f\u5728\u63a7\u5236\u8303\u56f4\u5185\u3002", "\u591a\u6570\u65e5\u5b50\u5b9e\u73b0\u4e86\u8d85\u8fc710,000\u6b65\u7684\u6d3b\u52a8\u91cf\uff0c\u5e76\u7ed3\u5408\u4e86\u722c\u697c\u68af\u7b49\u6d3b\u52a8\uff0c\u663e\u793a\u4e86\u826f\u597d\u7684\u8fd0\u52a8\u79ef\u6781\u6027\u3002", "\u5e73\u5747\u7761\u7720\u65f6\u957f\u57fa\u672c\u4fdd\u6301\u57287.5\u5c0f\u65f6\uff0c\u4e3a\u8eab\u4f53\u6062\u590d\u63d0\u4f9b\u4e86\u4fdd\u969c\u3002", "\u86cb\u767d\u8d28\u6444\u5165\u91cf\u5927\u90e8\u5206\u65f6\u95f4\u80fd\u8fbe\u5230\u6216\u8d85\u8fc7\u4f53\u91cd\u516c\u65a4\u6570\uff08g\uff09\u76840.8-1.2\u500d\uff0c\u5bf9\u808c\u8089\u4fdd\u7559\u975e\u5e38\u6709\u5229\u3002"], "actionableTips": ["**\u5173\u6ce8\u65e9\u9910\u7684\u5b8c\u6574\u6027**: \u786e\u4fdd\u60a8\u5728\u8bb0\u5f55\u65e9\u9910\u65f6\u63d0\u4f9b\u66f4\u8be6\u7ec6\u7684\u98df\u6750\u548c\u4efd\u91cf\u4fe1\u606f\uff0c\u7279\u522b\u662f\u57288\u67082\u65e5\u30018\u67088\u65e5\u548c8\u670820\u65e5\uff0c\u8fd9\u4e9b\u65e5\u5b50\u7684\u65e9\u9910\u6570\u636e\u7f3a\u5931\u6216\u4e0d\u51c6\u786e\u3002", "**\u5e73\u8861\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165**: \u907f\u514d\u5728\u67d0\u4e9b\u65e5\u5b50\uff08\u59828\u67081\u65e5\u30018\u670812\u65e5\u30018\u670814\u65e5\uff09\u7684\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u8fc7\u9ad8\uff0c\u53ef\u9002\u5ea6\u51cf\u5c11\u7cbe\u5236\u78b3\u6c34\u5316\u5408\u7269\uff0c\u589e\u52a0\u852c\u83dc\u3001\u85af\u7c7b\u7b49\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\u7684\u6444\u5165\u3002", "**\u4f18\u5316\u665a\u9910\u70ed\u91cf**: \u5728\u70ed\u91cf\u6444\u5165\u8f83\u4f4e\u7684\u65e5\u5b50\uff08\u59828\u670821\u65e5\uff09\uff0c\u867d\u7136\u8fd0\u52a8\u91cf\u5927\uff0c\u4f46\u4ecd\u5efa\u8bae\u5728\u665a\u9910\u65f6\u8865\u5145\u9002\u91cf\u4e14\u8425\u517b\u5bc6\u96c6\u7684\u98df\u7269\uff0c\u4ee5\u907f\u514d\u957f\u671f\u8fc7\u5ea6\u70ed\u91cf\u8d64\u5b57\u3002", "**\u63d0\u5347\u6c34\u5206\u6444\u5165**: \u5c3d\u7ba1\u5e73\u5747\u996e\u6c34\u91cf\u5c1a\u53ef\uff0c\u4f46\u5728\u9ad8\u5f3a\u5ea6\u8fd0\u52a8\u65e5\uff0c\u5efa\u8bae\u5c06\u996e\u6c34\u91cf\u589e\u52a0\u81f32.5-3\u5347\uff0c\u4ee5\u63d0\u9ad8\u65b0\u9648\u4ee3\u8c22\u6548\u7387\u5e76\u8f85\u52a9\u8eab\u4f53\u673a\u80fd\u3002", "**\u6ce8\u610f\u70f9\u996a\u65b9\u5f0f**: \u5c3d\u91cf\u9009\u62e9\u84b8\u3001\u716e\u3001\u70e4\u7b49\u4f4e\u6cb9\u70f9\u996a\u65b9\u5f0f\uff0c\u51cf\u5c11\u6cb9\u70b8\u548c\u8fc7\u591a\u8c03\u5473\u54c1\u7684\u4f7f\u7528\uff0c\u4ee5\u63a7\u5236\u603b\u8102\u80aa\u548c\u94a0\u7684\u6444\u5165\u3002", "**\u589e\u52a0\u5065\u5eb7\u8102\u80aa**: \u9002\u5ea6\u589e\u52a0\u725b\u6cb9\u679c\u3001\u575a\u679c\u3001\u6a44\u6984\u6cb9\u7b49\u5065\u5eb7\u8102\u80aa\u7684\u6444\u5165\uff0c\u5b83\u4eec\u6709\u52a9\u4e8e\u9971\u8179\u611f\u548c\u5fc5\u9700\u8102\u80aa\u9178\u7684\u8865\u5145\u3002"], "recommendedSuperfoods": [{"food": "\u725b\u6cb9\u679c", "reason": "\u5bcc\u542b\u5355\u4e0d\u9971\u548c\u8102\u80aa\u9178\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u3001\u63d0\u4f9b\u80fd\u91cf\uff0c\u5e76\u542b\u6709\u591a\u79cd\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\u3002\u53ef\u5728\u6c99\u62c9\u6216\u4f5c\u4e3a\u9910\u98df\u7684\u4e00\u90e8\u5206\u6444\u5165\u3002"}, {"food": "\u5e0c\u814a\u9178\u5976", "reason": "\u86cb\u767d\u8d28\u542b\u91cf\u6781\u9ad8\uff0c\u540c\u65f6\u542b\u6709\u76ca\u751f\u83cc\uff0c\u6709\u52a9\u4e8e\u6d88\u5316\u548c\u9971\u8179\u611f\u3002\u53ef\u4f5c\u4e3a\u65e9\u9910\u6216\u52a0\u9910\uff0c\u66ff\u4ee3\u90e8\u5206\u9ad8\u78b3\u6c34\u98df\u7269\u3002"}, {"food": "\u897f\u5170\u82b1", "reason": "\u5bcc\u542b\u7ef4\u751f\u7d20C\u3001K\u3001\u7ea4\u7ef4\u7d20\u548c\u591a\u79cd\u6297\u6c27\u5316\u5242\uff0c\u70ed\u91cf\u4f4e\u4e14\u9971\u8179\u611f\u5f3a\u3002\u662f\u4f18\u79c0\u81b3\u98df\u7ea4\u7ef4\u548c\u5fae\u91cf\u8425\u517b\u7d20\u7684\u6765\u6e90\u3002"}, {"food": "\u4e09\u6587\u9c7c", "reason": "\u5bcc\u542bOmega-3\u8102\u80aa\u9178\uff0c\u5bf9\u5fc3\u8840\u7ba1\u5065\u5eb7\u548c\u6297\u708e\u6709\u76ca\uff0c