\u5316\u5408\u7269\u548c\u8102\u80aa\u7684\u6bd4\u4f8b\u5728\u67d0\u4e9b\u5929\u7565\u663e\u504f\u9ad8\uff0c\u5c24\u5176\u662f\u5728\u5348\u9910\u548c\u665a\u9910\u65f6\u6bb5\u3002", "positive": "\u603b\u4f53\u70ed\u91cf\u6444\u5165\u63a7\u5236\u5f97\u5f53\uff0c\u5927\u591a\u6570\u65e5\u5b50\u7ef4\u6301\u57281000-1800\u5927\u5361\u4e4b\u95f4\uff0c\u8fd9\u4e3a\u60a8\u521b\u9020\u4e86\u663e\u8457\u7684\u70ed\u91cf\u8d64\u5b57\uff0c\u662f\u4f53\u91cd\u4e0b\u964d\u7684\u6839\u672c\u539f\u56e0\u3002\u86cb\u767d\u8d28\u6444\u5165\u5728\u591a\u6570\u65e5\u5b50\u91cc\u8fbe\u5230\u4e86\u4f53\u91cd\uff08\u6bcf\u516c\u65a41\u514b\u4ee5\u4e0a\uff09\u7684\u63a8\u8350\u91cf\uff0c\u4e3a\u808c\u8089\u7684\u7ef4\u6301\u63d0\u4f9b\u4e86\u652f\u6301\u3002", "improvement": "\u90e8\u5206\u65e5\u671f\u7684\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u91cf\u5360\u6bd4\u504f\u9ad8\uff0c\u800c\u4e00\u4e9b\u65e5\u5b50\u7684\u603b\u70ed\u91cf\u6444\u5165\u8fc7\u4f4e\uff0c\u53ef\u80fd\u5f71\u54cd\u80fd\u91cf\u50a8\u5907\u548c\u65b0\u9648\u4ee3\u8c22\u7684\u7a33\u5b9a\u6027\u3002\u65e9\u9910\u7684\u6784\u6210\u6709\u65f6\u8f83\u4e3a\u5355\u4e00\uff0c\u53ef\u80fd\u7f3a\u4e4f\u8db3\u591f\u7684\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\u548c\u5065\u5eb7\u8102\u80aa\u3002\u4f8b\u5982\uff0c2025-08-02\u7684\u65e9\u9910\u70ed\u91cf\u6444\u5165\u4ec5300\u5343\u5361\uff0c\u86cb\u767d\u8d2811\u514b\uff0c\u800c\u5348\u9910\u548c\u665a\u9910\u7684\u70ed\u91cf\u4e5f\u8f83\u4f4e\uff0c\u5bfc\u81f4\u5168\u5929\u603b\u6444\u5165\u4ec5600\u5343\u5361\uff0c\u8fd9\u5bf9\u4e8e\u60a8\u76ee\u524d\u7684\u4f53\u91cd\u6765\u8bf4\uff0c\u53ef\u80fd\u8fc7\u4e8e\u6781\u7aef\uff0c\u6709\u5bfc\u81f4\u808c\u8089\u6d41\u5931\u7684\u98ce\u9669\u3002", "macroDistribution": {"proteinPercentage": 28.4, "carbsPercentage": 45.6, "fatPercentage": 26.0, "comment": "\u5b8f\u91cf\u8425\u517b\u7d20\u7684\u5e73\u5747\u6bd4\u4f8b\u4e3a\u86cb\u767d\u8d2828.4%\uff0c\u78b3\u6c34\u5316\u5408\u726945.6%\uff0c\u8102\u80aa26.0%\u3002\u8fd9\u4e2a\u6bd4\u4f8b\u5728\u6574\u4f53\u4e0a\u662f\u76f8\u5bf9\u5747\u8861\u7684\uff0c\u4f46\u90e8\u5206\u65e5\u671f\u504f\u79bb\u4e86\u6700\u4f73\u6bd4\u4f8b\u3002\u4f8b\u5982\uff0c2025-08-01\u7684\u78b3\u6c34\u5316\u5408\u7269\u5360\u6bd4\u8f83\u9ad8(\u7ea648%)\uff0c\u800c2025-08-20\u7684\u78b3\u6c34\u5316\u5408\u7269(\u7ea638%)\u548c\u8102\u80aa(\u7ea629%)\u6bd4\u4f8b\u6709\u6240\u8c03\u6574\uff0c\u86cb\u767d\u8d28(\u7ea629%)\u5f97\u5230\u52a0\u5f3a\u3002\u7406\u60f3\u7684\u6bd4\u4f8b\u5e94\u662f\u6839\u636e\u60a8\u7684\u6d3b\u52a8\u6c34\u5e73\u548c\u51cf\u91cd\u76ee\u6807\u8fdb\u884c\u52a8\u6001\u8c03\u6574\uff0c\u4f46\u603b\u4f53\u4e0a\uff0c\u5e94\u7ee7\u7eed\u4fdd\u6301\u86cb\u767d\u8d28\u7684\u76f8\u5bf9\u9ad8\u6444\u5165\uff0c\u5e76\u5c06\u90e8\u5206\u78b3\u6c34\u5316\u5408\u7269\u66ff\u6362\u4e3a\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\u548c\u5065\u5eb7\u8102\u80aa\u3002"}}, "achievements": ["\u5728\u77ed\u77ed22\u5929\u5185\u6210\u529f\u51cf\u6389\u4e8610.25\u516c\u65a4\u4f53\u91cd\uff0c\u5e73\u5747\u6bcf\u5468\u51cf\u91cd3.26\u516c\u65a4\uff0c\u901f\u5ea6\u975e\u5e38\u663e\u8457\uff0c\u8fdc\u8d85\u5065\u5eb7\u51cf\u91cd\u5efa\u8bae\uff08\u6bcf\u54680.5-1\u516c\u65a4\uff09\uff0c\u4f46\u4ece\u8d8b\u52bf\u770b\uff0c\u524d\u4e24\u5468\u51cf\u91cd\u6548\u679c\u5c24\u4e3a\u7a81\u51fa\u3002", "\u8170\u56f4\u51cf\u5c11\u4e863.0\u5398\u7c73\uff0c\u8fd9\u8868\u660e\u8eab\u4f53\u7684\u8102\u80aa\u5206\u5e03\u6b63\u5728\u5411\u79ef\u6781\u65b9\u5411\u6539\u53d8\u3002", "\u4fdd\u6301\u4e86\u9ad8\u8d28\u91cf\u7684\u65e5\u5fd7\u8bb0\u5f55\uff0c\u6bcf\u5929\u90fd\u6709\u5b8c\u6574\u7684\u6570\u636e\u8f93\u5165\uff0c\u8fd9\u4e3a\u60a8\u63d0\u4f9b\u4e86\u4e00\u4e2a\u575a\u5b9e\u7684\u6570\u636e\u57fa\u7840\u6765\u8fdb\u884c\u5206\u6790\u548c\u8c03\u6574\u3002", "\u7edd\u5927\u591a\u6570\u65e5\u671f\u4fdd\u6301\u4e86\u5145\u8db3\u7684\u7761\u7720\uff08\u5e73\u57477.58\u5c0f\u65f6\uff09\uff0c\u8fd9\u5bf9\u4e8e\u8eab\u4f53\u6062\u590d\u548c\u6fc0\u7d20\u5e73\u8861\u81f3\u5173\u91cd\u8981\u3002", "\u79ef\u6781\u53c2\u4e0e\u8fd0\u52a8\uff0c\u5e73\u5747\u6bcf\u5929\u6d88\u8017\u7ea6422\u5343\u5361\uff0c\u7279\u522b\u662f\u6b65\u6570\u548c\u722c\u697c\u7684\u8bb0\u5f55\u663e\u793a\u60a8\u5728\u52aa\u529b\u589e\u52a0\u6d3b\u52a8\u91cf\u3002"], "actionableTips": ["**\u7a33\u5b9a\u70ed\u91cf\u6444\u5165**: \u907f\u514d\u6781\u4f4e\u70ed\u91cf\u65e5\uff08\u59822025-08-02\u7684600\u5927\u5361\uff09\u3002\u5efa\u8bae\u60a8\u7684\u65e5\u5747\u70ed\u91cf\u6444\u5165\u7ef4\u6301\u57281500-1700\u5927\u5361\u4e4b\u95f4\uff0c\u4e3a\u8eab\u4f53\u63d0\u4f9b\u5fc5\u8981\u7684\u80fd\u91cf\uff0c\u540c\u65f6\u7ef4\u6301\u5065\u5eb7\u7684\u70ed\u91cf\u8d64\u5b57\u3002", "**\u4f18\u5316\u65e9\u9910\u8425\u517b**: \u786e\u4fdd\u65e9\u9910\u542b\u6709\u5145\u8db3\u7684\u86cb\u767d\u8d28\uff08\u81f3\u5c1115-20\u514b\uff09\u548c\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\u3002\u4f8b\u5982\uff0c\u53ef\u4ee5\u5728\u65e9\u9910\u4e2d\u589e\u52a0\u4e00\u4efd\u5e0c\u814a\u9178\u5976\u3001\u716e\u9e21\u86cb\uff0c\u6216\u5c06\u7389\u7c73\u66ff\u6362\u4e3a\u71d5\u9ea6\u3002\u907f\u514d\u9ad8\u7cd6\u3001\u7cbe\u52a0\u5de5\u7684\u65e9\u9910\u98df\u54c1\u3002", "**\u589e\u52a0\u5065\u5eb7\u8102\u80aa**: \u9002\u91cf\u589e\u52a0\u5bcc\u542b\u5065\u5eb7\u8102\u80aa\u7684\u98df\u7269\uff0c\u5982\u725b\u6cb9\u679c\u3001\u575a\u679c\u3001\u79cd\u5b50\u7c7b\uff0c\u4ee5\u53ca\u5bcc\u542bOmega-3\u7684\u9c7c\u7c7b\uff08\u5982\u4e09\u6587\u9c7c\uff09\u3002\u8fd9\u6709\u52a9\u4e8e\u63d0\u9ad8\u9971\u8179\u611f\uff0c\u5e76\u5bf9\u6fc0\u7d20\u5206\u6ccc\u548c\u6574\u4f53\u5065\u5eb7\u6709\u76ca\u3002", "**\u5173\u6ce8\u70f9\u996a\u65b9\u5f0f**: \u503e\u5411\u4e8e\u9009\u62e9\u84b8\u3001\u716e\u3001\u70e4\u3001\u7096\u7b49\u4f4e\u6cb9\u70f9\u996a\u65b9\u5f0f\u3002\u867d\u7136\u5927\u90e8\u5206\u8bb0\u5f55\u4e2d\u70f9\u996a\u65b9\u5f0f\u8f83\u4e3a\u5065\u5eb7\uff0c\u4f46\u9700\u8b66\u60d5\u53ef\u80fd\u7684\u9690\u5f62\u6cb9\u8102\u6444\u5165\u3002", "**\u8c03\u6574\u8fd0\u52a8\u8ba1\u5212**: \u60a8\u7684\u8fd0\u52a8\u91cf\u5df2\u7ecf\u4e0d\u9519\uff0c\u4f46\u53ef\u4ee5\u8003\u8651\u5728\u529b\u91cf\u8bad\u7ec3\u7684\u5468\u671f\u6027\u4e2d\uff0c\u8fdb\u4e00\u6b65\u589e\u52a0\u8bad\u7ec3\u5f3a\u5ea6\u6216\u6539\u53d8\u8bad\u7ec3\u6a21\u5f0f\uff0c\u4ee5\u907f\u514d\u8eab\u4f53\u9002\u5e94\u671f\uff0c\u6301\u7eed\u63d0\u9ad8\u65b0\u9648\u4ee3\u8c22\u3002", "**\u91cd\u89c6\u665a\u9910\u8425\u517b**: \u907f\u514d\u201c\u672a\u8fdb\u98df\u665a\u9910\u201d\u7684\u60c5\u51b5\uff082025-08-21\uff09\uff0c\u5373\u4f7f\u5728\u51cf\u91cd\u671f\u95f4\uff0c\u665a\u9910\u4e5f\u5e94\u5305\u542b\u4f18\u8d28\u86cb\u767d\u8d28\u548c\u5927\u91cf\u852c\u83dc\uff0c\u4ee5\u652f\u6301\u591c\u95f4\u7684\u8eab\u4f53\u4fee\u590d\u3002"], "recommendedSuperfoods": [{"food": "\u5e0c\u814a\u9178\u5976", "reason": "\u5bcc\u542b\u9ad8\u5bc6\u5ea6\u86cb\u767d\u8d28\uff0c\u80fd\u63d0\u4f9b\u6301\u4e45\u7684\u9971\u8179\u611f\uff0c\u6709\u52a9\u4e8e\u7ef4\u6301\u808c\u8089\u91cf\uff0c\u5e76\u4e14\u5bcc\u542b\u76ca\u751f\u83cc\uff0c\u5bf9\u80a0\u9053\u5065\u5eb7\u6709\u76ca\u3002\u53ef\u4f5c\u4e3a\u65e9\u9910\u6216\u52a0\u9910\u7684\u4f18\u8d28\u9009\u62e9\u3002"}, {"food": "\u725b\u6cb9\u679c", "reason": "\u542b\u6709\u4e30\u5bcc\u7684\u5355\u4e0d\u9971\u548c\u8102\u80aa\u9178\uff0c\u6709\u52a9\u4e8e\u964d\u4f4e\u574f\u80c6\u56fa\u9187\uff0c\u540c\u65f6\u63d0\u4f9b\u81b3\u98df\u7ea4\u7ef4\u548c\u591a\u79cd\u7ef4\u751f\u7d20\uff0c\u80fd\u6709\u6548\u589e\u52a0\u9910\u98df\u7684\u9971\u8179\u611f\u548c\u8425\u517b\u5bc6\u5ea6\u3002"}, {"food": "\u85dc\u9ea6", "reason": "\u662f\u4e00\u79cd\u5b8c\u6574\u7684\u86cb\u767d\u8d28\u6765\u6e90\uff0c\u542b\u6709\u6240\u6709\u5fc5\u9700\u6c28\u57fa\u9178\uff0c\u5e76\u5bcc\u542b\u81b3\u98df\u7ea4\u7ef4\u3001\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\u3002\u662f\u7cd9\u7c73\u7b49\u78b3\u6c34\u5316\u5408\u7269\u7684\u4f18\u8d28\u66ff\u4ee3\u54c1\uff0c\u6709\u52a9\u4e8e\u5e73\u7a33\u8840\u7cd6\u3002"}, {"food": "\u575a\u679c\uff08\u5982\u674f\u4ec1\u3001\u6838\u6843\uff09", "reason": "\u662f\u5065\u5eb7\u8102\u80aa\u3001\u86cb\u767d\u8d28\u3001\u7ea4\u7ef4\u548c\u5fae\u91cf\u5143\u7d20\u7684\u826f\u597d\u6765\u6e90\u3002\u9002\u91cf\u98df\u7528\u53ef\u4ee5\u63d0\u4f9b\u6301\u4e45\u7684\u80fd\u91cf\uff0c\u5e76\u6709\u52a9\u4e8e\u964d\u4f4e\u5fc3\u8840\u7ba1\u75be\u75c5\u98ce\u9669\u3002\u8bf7\u6ce8\u610f\u63a7\u5236\u4efd\u91cf\uff0c\u56e0\u4e3a\u575a\u679c\u70ed\u91cf\u5bc6\u5ea6\u8f83\u9ad8\u3002"}, {"food": "\u7eff\u53f6\u852c\u83dc\uff08\u5982\u83e0\u83dc\u3001\u7fbd\u8863\u7518\u84dd\uff09", "reason": "\u5bcc\u542b\u7ef4\u751f\u7d20\uff08A, C, K\uff09\u3001\u77ff\u7269\u8d28\uff08\u94c1, \u9499\uff09\u548c\u6297\u6c27\u5316\u5242\u3002\u4f4e\u70ed\u91cf\u9ad8\u7ea4\u7ef4\uff0c\u662f\u589e\u52a0\u9910\u98df\u4f53\u79ef\u3001\u63d0\u5347\u8425\u517b\u5bc6\u5ea6\u7684\u7406\u60f3\u9009\u62e9\u3002"}], "exercisePrescription": {"recommendation": "\u9274\u4e8e\u60a8\u76ee\u524d\u7684\u8fd0\u52a8\u4e60\u60ef\u548c\u51cf\u91cd\u8d8b\u52bf\uff0c\u5efa\u8bae\u5728\u4fdd\u6301\u73b0\u6709\u6709\u6c27\u6d3b\u52a8\uff08\u6b65\u6570\u3001\u722c\u697c\uff09\u7684\u57fa\u7840\u4e0a\uff0c\u9010\u6b65\u589e\u52a0\u529b\u91cf\u8bad\u7ec3\u7684\u5f3a\u5ea6\u548c\u8bad\u7ec3\u9891\u7387\uff0c\u4ee5\u6700\u5927\u5316\u808c\u8089\u751f\u957f\u548c\u4ee3\u8c22\u7387\u3002", "details": ["**\u529b\u91cf\u8bad\u7ec3**: \u76ee\u6807\u662f\u5c06\u6bcf\u5468\u7684\u529b\u91cf\u8bad\u7ec3\u9891\u7387\u589e\u52a0\u52303-4\u6b21\u3002\u6bcf\u6b21\u8bad\u7ec3\u5e94\u5305\u542b\u590d\u5408\u52a8\u4f5c\uff0c\u5982\u6df1\u8e72\u3001\u786c\u62c9\u3001\u5367\u63a8\u3001\u5212\u8239\u3001\u5f15\u4f53\u5411\u4e0a\u7b49\uff0c\u6bcf\u4e2a\u52a8\u4f5c\u8fdb\u884c3-4\u7ec4\uff0c\u6bcf\u7ec48-12\u6b21\u3002\u60a8\u53ef\u4ee5\u8003\u8651\u91c7\u7528\u5206\u5316\u8bad\u7ec3\u8ba1\u5212\uff0c\u4f8b\u5982\u4e0a\u534a\u8eab/\u4e0b\u534a\u8eab\u5206\u5316\uff0c\u6216\u63a8/\u62c9/\u817f\u5206\u5316\u3002", "**\u6709\u6c27\u8fd0\u52a8**: \u5728\u975e\u529b\u91cf\u8bad\u7ec3\u65e5\uff0c\u53ef\u5c06\u5feb\u8d70\u548c\u6162\u8dd1\u7ed3\u5408\uff0c\u4fdd\u6301\u6bcf\u54683-4\u6b21\uff0c\u6bcf\u6b2130-45\u5206\u949f\u3002\u53ef\u4ee5\u5c1d\u8bd5HIIT\uff08\u9ad8\u5f3a\u5ea6\u95f4\u6b47\u8bad\u7ec3\uff09\u6765\u8fdb\u4e00\u6b65\u63d0\u5347\u71c3\u8102\u6548\u7387\uff0c\u4f46\u9700\u5faa\u5e8f\u6e10\u8fdb\u3002", "**\u7075\u6d3b\u6027\u548c\u6062\u590d**: \u7eb3\u5165\u6ce1\u6cab\u8f74\u653e\u677e\u548c\u9759\u6001\u62c9\u4f38\uff0c\u6bcf\u6b21\u8bad\u7ec3\u540e\u8fdb\u884c10-15\u5206\u949f\uff0c\u4ee5\u4fc3\u8fdb\u808c\u8089\u6062\u590d\uff0c\u51cf\u5c11\u635f\u4f24\u98ce\u9669\u3002", "**\u8fd0\u52a8\u76d1\u6d4b**: \u5efa\u8bae\u4f7f\u7528\u5fc3\u7387\u76d1\u6d4b\u5668\u6765\u8bc4\u4f30\u8fd0\u52a8\u5f3a\u5ea6\uff0c\u786e\u4fdd\u8fbe\u5230\u6709\u6c27\u8fd0\u52a8\u7684\u6709\u6548\u5fc3\u7387\u533a\u95f4\u3002"]}, "potentialRisks": ["**\u77ed\u671f\u5185\u4f53\u91cd\u4e0b\u964d\u8fc7\u5feb**\uff1a\u60a8\u524d\u4e24\u5468\u7684\u51cf\u91cd\u901f\u5ea6\uff08\u5e73\u5747\u6bcf\u5468\u8d85\u8fc73\u516c\u65a4\uff09\u8fdc\u9ad8\u4e8e\u5065\u5eb7\u7684\u6bcf\u54680.5-1\u516c\u65a4\u3002\u867d\u7136\u521d\u671f\u4f53\u91cd\u57fa\u6570\u5927\uff0c\u6c34\u5206\u548c\u7cd6\u539f\u6d88\u8017\u4f1a\u52a0\u901f\u51cf\u91cd\uff0c\u4f46\u5982\u6b64\u5feb\u7684\u901f\u5ea6\u53ef\u80fd\u5bfc\u81f4\u808c\u8089\u6d41\u5931\u3001\u4ee3\u8c22\u7d0a\u4e71\uff0c\u5e76\u589e\u52a0\u53cd\u5f39\u7684\u98ce\u9669\u3002", "**\u70ed\u91cf\u6444\u5165\u4e0d\u7a33\u4e14\u8fc7\u4f4e**\uff1a\u57282025-08-02\uff08600\u5927\u5361\uff09\u548c2025-08-21\uff081000\u5927\u5361\uff09\u7b49\u65e5\u671f\uff0c\u60a8\u7684\u603b\u70ed\u91cf\u6444\u5165\u8fdc\u4f4e\u4e8e\u57fa\u7840\u4ee3\u8c22\u7387(BMR)\u548c\u6d3b\u52a8\u6d88\u8017\uff0c\u8fd9\u79cd\u6781\u7aef\u7684\u70ed\u91cf\u9650\u5236\u4e0d\u5229\u4e8e\u957f\u671f\u575a\u6301\uff0c\u4e14\u53ef\u80fd\u5bfc\u81f4\u8eab\u4f53\u8fdb\u5165\u201c\u9965\u997f\u6a21\u5f0f\u201d\uff0c\u964d\u4f4e\u4ee3\u8c22\u7387\uff0c\u5f71\u54cd\u84