\u589e\u52a0\u989d\u5916\u70ed\u91cf\u6444\u5165", "\u6574\u4f53\u70ed\u91cf\uff08710 kcal\uff09\u5bf9\u4e8e\u90e8\u5206\u51cf\u8102\u671f\u4e2a\u4f53\u53ef\u80fd\u504f\u9ad8\uff0c\u9700\u6839\u636e\u6bcf\u65e5\u603b\u70ed\u91cf\u6444\u5165\u8fdb\u884c\u8c03\u6574"], "improvementTips": ["\u5728\u51c9\u62cc\u8304\u5b50\u548c\u7092\u9752\u83dc\u4e2d\uff0c\u5c3d\u91cf\u51cf\u5c11\u70f9\u996a\u7528\u6cb9\uff0c\u5e76\u9009\u62e9\u4f7f\u7528\u66f4\u5065\u5eb7\u7684\u6cb9\u54c1\uff08\u5982\u6a44\u6984\u6cb9\u3001\u83dc\u7c7d\u6cb9\uff09\uff0c\u5e76\u63a7\u5236\u8c03\u5473\u6599\uff08\u5982\u9171\u6cb9\u3001\u918b\u3001\u7cd6\uff09\u7684\u7528\u91cf\uff0c\u7279\u522b\u662f\u7cd6\u548c\u6cb9\u7684\u7528\u91cf\u3002", "\u786e\u4fdd\u6e05\u84b8\u9c7c\u548c\u767d\u707c\u867e\u7684\u70f9\u996a\u8fc7\u7a0b\u4e2d\u4e0d\u989d\u5916\u6dfb\u52a0\u6cb9\u8102\u3002", "\u5982\u679c\u53ef\u80fd\uff0c\u9009\u62e9\u975e\u6cb9\u70b8\u7c7b\u7684\u8c03\u5473\u54c1\uff0c\u4f8b\u5982\u4f7f\u7528\u5c11\u91cf\u9999\u6cb9\u3001\u849c\u6ce5\u3001\u59dc\u672b\u3001\u8fa3\u6912\u63d0\u5473\u3002", "\u6839\u636e\u5f53\u65e5\u6574\u4f53\u996e\u98df\u5b89\u6392\uff0c\u5982\u679c\u6b64\u9910\u70ed\u91cf\u504f\u9ad8\uff0c\u53ef\u9002\u5f53\u51cf\u5c11\u7389\u7c73\u7684\u4efd\u91cf\uff0c\u6216\u5c06\u4e00\u90e8\u5206\u86cb\u767d\u8d28\uff08\u5982\u867e\uff09\u66ff\u6362\u4e3a\u4f4e\u70ed\u91cf\u852c\u83dc\u3002"]}','2025-08-20 09:54:19');
INSERT INTO meal_logs VALUES(506,172,'dinner','白灼虾, 清蒸鱼, 凉拌茄子, 凉拌豆腐, 炒青菜, 白薯 (710 kcal)',NULL,'{"generatedMealName": "\u5bb6\u5e38\u6e05\u6de1\u84b8\u716e\u6d77\u9c9c\u852c\u83dc\u9910", "estimatedCalories": 710, "estimatedProteinG": 55.0, "estimatedCarbsG": 60.0, "estimatedFatG": 25.0, "description": "\u8fd9\u987f\u665a\u9910\u5305\u542b\u767d\u707c\u867e\u3001\u6e05\u84b8\u9c7c\u3001\u51c9\u62cc\u8304\u5b50\u3001\u51c9\u62cc\u8c46\u8150\u3001\u7092\u9752\u83dc\u4ee5\u53ca\u4e00\u4efd\u767d\u85af\u3002\u6574\u4f53\u4ee5\u84b8\u3001\u716e\u3001\u51c9\u62cc\u7684\u70f9\u996a\u65b9\u5f0f\u4e3a\u4e3b\uff0c\u642d\u914d\u5c11\u91cf\u7092\u9752\u83dc\u3002\u767d\u707c\u867e\u548c\u6e05\u84b8\u9c7c\u63d0\u4f9b\u4e86\u4e30\u5bcc\u7684\u4f18\u8d28\u86cb\u767d\u8d28\uff0c\u51c9\u62cc\u8304\u5b50\u548c\u7092\u9752\u83dc\u63d0\u4f9b\u4e86\u81b3\u98df\u7ea4\u7ef4\u548c\u7ef4\u751f\u7d20\uff0c\u767d\u85af\u4f5c\u4e3a\u4e3b\u98df\u63d0\u4f9b\u78b3\u6c34\u5316\u5408\u7269\u3002\u51c9\u62cc\u83dc\u4e2d\u53ef\u80fd\u542b\u6709\u4e00\u5b9a\u7684\u6cb9\u8102\u548c\u8c03\u5473\u6599\uff0c\u7092\u9752\u83dc\u7684\u7528\u6cb9\u91cf\u4e5f\u9700\u8981\u6ce8\u610f\u3002", "tags": ["\u9ad8\u86cb\u767d", "\u4f4e\u8102\u70f9\u996a", "\u5bcc\u542b\u7ea4\u7ef4", "\u5747\u8861\u8425\u517b", "\u51cf\u8102\u53cb\u597d"], "identifiedIngredients": ["\u867e", "\u9c7c", "\u8304\u5b50", "\u8c46\u8150", "\u9752\u83dc", "\u767d\u85af"], "dominantColors": ["\u767d\u8272", "\u7eff\u8272", "\u6a59\u8272", "\u6de1\u7d2b\u8272"], "cuisineStyle": "\u4e2d\u5f0f\u5bb6\u5e38", "fatLossRating": 7, "fatLossAdvantages": ["\u86cb\u767d\u8d28\u542b\u91cf\u9ad8\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u548c\u7ef4\u6301\u808c\u8089\u91cf\u3002", "\u4e3b\u8981\u70f9\u996a\u65b9\u5f0f\u4e3a\u84b8\u3001\u716e\u3001\u51c9\u62cc\uff0c\u76f8\u5bf9\u5065\u5eb7\uff0c\u6cb9\u8102\u6444\u5165\u8f83\u4f4e\u3002", "\u5305\u542b\u591a\u79cd\u852c\u83dc\uff0c\u63d0\u4f9b\u4e30\u5bcc\u7684\u81b3\u98df\u7ea4\u7ef4\u548c\u7ef