\u5170\u82b1\u3001\u83e0\u83dc\u3001\u9ec4\u74dc\u7b49\uff0c\u4ee5\u8fdb\u4e00\u6b65\u63d0\u9ad8\u9971\u8179\u611f\u548c\u8425\u517b\u5bc6\u5ea6\u3002", "\u5982\u679c\u6761\u4ef6\u5141\u8bb8\uff0c\u5c06\u7092\u9752\u83dc\u6539\u4e3a\u84b8\u716e\u6216\u51c9\u62cc\uff08\u6ce8\u610f\u8c03\u5473\uff09\u53ef\u4ee5\u8fdb\u4e00\u6b65\u51cf\u5c11\u6cb9\u8102\u6444\u5165\u3002", "\u786e\u4fdd\u86cb\u767d\u8d28\u6765\u6e90\uff08\u867e\u3001\u9c7c\uff09\u7684\u70f9\u996a\u65b9\u5f0f\u4ee5\u84b8\u3001\u716e\u3001\u70e4\u4e3a\u4e3b\uff0c\u907f\u514d\u6cb9\u70b8\u6216\u7ea2\u70e7\u3002"]}','2025-08-20 09:54:19');
INSERT INTO meal_logs VALUES(507,173,'breakfast','脱脂牛奶 + 西红柿 + 鸡蛋 + 玉米 (275 kcal)',NULL,'{"generatedMealName": "\u725b\u5976\u756a\u8304\u9e21\u86cb\u7389\u7c73\u65e9\u9910", "estimatedCalories": 275, "estimatedProteinG": 20.0, "estimatedCarbsG": 25.0, "estimatedFatG": 10.0, "description": "\u4e00\u676f\u8131\u8102\u725b\u5976\uff0c\u642d\u914d\u4e00\u4e2a\u4e2d\u7b49\u5927\u5c0f\u7684\u897f\u7ea2\u67ff\uff0c\u4e00\u4e2a\u6c34\u716e\u86cb\uff0c\u4ee5\u53ca\u4e00\u5c0f\u6bb5\u716e\u7389\u7c73\uff08\u7ea6100\u514b\uff09\u3002", "tags": ["\u65e9\u9910", "\u51cf\u8102", "\u9ad8\u86cb\u767d", "\u590d\u5408\u78b3\u6c34", "\u7ef4\u751f\u7d20"], "identifiedIngredients": ["\u8131\u8102\u725b\u5976", "\u897f\u7ea2\u67ff", "\u9e21\u86cb", "\u7389\u7c73"], "dominantColors": ["\u7ea2\u8272", "\u9ec4\u8272", "\u767d\u8272"], "cuisineStyle": "\u5bb6\u5e38", "fatLossRating": 8, "fatLossAdvantages": ["\u86cb\u767d\u8d28\u542b\u91cf\u8f83\u9ad8\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\uff0c\u7ef4\u6301\u808c\u8089\u91cf\u3002", "\u542b\u6709\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff08\u7389\u7c73\uff09\uff0c\u80fd\u63d0\u4f9b\u6301\u4e45\u80fd\u91cf\u3002", "\u5bcc\u542b\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\uff08\u756a\u8304\u3001\u7389\u7c73\u3001\u9e21\u86cb\uff09\u3002", "\u8131\u8102\u725b\u5976\u70ed\u91cf\u8f83\u4f4e\uff0c\u8102\u80aa\u542b\u91cf\u5c11\u3002", "\u6574\u4f53\u70ed\u91cf\u63a7\u5236\u5728275\u5927\u5361\uff0c\u7b26\u5408\u51cf\u8102\u671f\u65e9\u9910\u5efa\u8bae\u3002"], "fatLossDisadvantages": ["\u78b3\u6c34\u5316\u5408\u7269\u6765\u6e90\u76f8\u5bf9\u5355\u4e00\uff08\u4e3b\u8981\u4e3a\u7389\u7c73\uff09\uff0c\u867d\u7136\u662f\u590d\u5408\u78b3\u6c34\uff0c\u4f46\u53ef\u4ee5\u589e\u52a0\u81b3\u98df\u7ea4\u7ef4\u6444\u5165\u3002", "\u8102\u80aa\u542b\u91cf\u53ef\u4ee5\u8fdb\u4e00\u6b65\u4f18\u5316\uff0c\u5c3d\u7ba1\u76ee\u524d\u4e0d\u7b97\u9ad8\u3002"], "improvementTips": ["\u5c06\u7389\u7c73\u7684\u6444\u5165\u91cf\u7a0d\u5fae\u51cf\u5c11\uff0c\u6216\u66ff\u6362\u4e3a\u90e8\u5206\u5168\u9ea6\u9762\u5305\u6216\u71d5\u9ea6\uff0c\u589e\u52a0\u81b3\u98df\u7ea4\u7ef4\u548c\u591a\u79cd\u7ef4\u751f\u7d20\u3002", "\u756a\u8304\u53ef\u4ee5\u751f\u5403\u6216\u84b8\u716e\uff0c\u907f\u514d\u6cb9\u70b8\u3002", "\u9e21\u86cb\u53ef\u4ee5\u9009\u62e9\u6c34\u716e\u86cb\u6216\u84b8\u86cb\uff0c\u907f\u514d\u6cb9\u714e\u3002", "\u5982\u679c\u60f3\u589e\u52a0\u9910\u98df\u7684\u9971\u8179\u611f\u548c\u8425\u517b\u5bc6\u5ea6\uff0c\u53ef\u4ee5\u52a0\u5165\u5c11\u91cf\u852c\u83dc\uff0c\u5982\u83e0\u83dc\u6216\u9ec4\u74dc\u3002", "\u8003\u8651\u5c06\u8131\u8102\u725b\u5976\u66ff\u6362\u4e3a\u65e0\u7cd6\u8c46\u6d46\uff0c\u4ee5\u6444\u53d6\u66f4\u591a\u690d\u7269\u86cb\u767d\u548c\u81b3\u98df\u7ea4\u7ef4\u3002"]}','2025-08-20 09:54:19');
INSERT INTO meal_logs VALUES(508,173,'lunch','蔬菜沙拉 + 盐焗牛肉 + 1个鸡蛋 + 一小口糙米饭 (410 kcal)',NULL,'{"generatedMealName": "\u852c\u83dc\u6c99\u62c9\u914d\u76d0\u7117\u725b\u8089\u548c\u5c11\u91cf\u7cd9\u7c73\u996d", "estimatedCalories": 410, "estimatedProteinG": 30.0, "estimatedCarbsG": 30.0, "estimatedFatG": 18.0, "description": "\u4e00\u4efd\u4ee5\u5404\u7c7b\u852c\u83dc\u4e3a\u57fa\u5e95\u7684\u6c99\u62c9\uff0c\u642d\u914d\u76d0\u7117\u5904\u7406\u7684\u725b\u8089\u5757\uff0c\u5e76\u4f50\u4ee5\u4e00\u5c0f\u4efd\u7cd9\u7c73\u996d\u3002\u725b\u8089\u7684\u989c\u8272\u5448\u8910\u8272\uff0c\u5e26\u6709\u5fae\u7126\u7684\u8d28\u611f\u3002", "tags": ["\u5747\u8861", "\u51cf\u8102", "\u9ad8\u86cb\u767d", "\u9ad8\u7ea4\u7ef4", "\u590d\u5408\u78b3\u6c34"], "identifiedIngredients": ["\u6df7\u5408\u852c\u83dc", "\u725b\u8089", "\u9e21\u86cb", "\u7cd9\u7c73\u996d"], "dominantColors": ["\u7eff\u8272", "\u68d5\u8272", "\u767d\u8272"], "cuisineStyle": "\u897f\u5f0f/\u901a\u7528", "fatLossRating": 7, "fatLossAdvantages": ["\u63d0\u4f9b\u4f18\u8d28\u86cb\u767d\u8d28\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u548c\u7ef4\u6301\u808c\u8089\u91cf\u3002", "\u542b\u6709\u4e30\u5bcc\u7684\u81b3\u98df\u7ea4\u7ef4\uff0c\u6765\u81ea\u852c\u83dc\u548c\u7cd9\u7c73\uff0c\u6709\u52a9\u4e8e\u80a0\u9053\u5065\u5eb7\u548c\u63a7\u5236\u8840\u7cd6\u3002", "\u80fd\u91cf\u63a7\u5236\u5728\u5408\u7406\u8303\u56f4\u5185\uff0c\u7b26\u5408\u51cf\u8102\u671f\u9910\u98df\u80fd\u91cf\u9700\u6c42\u3002"], "fatLossDisadvantages": ["\u76d0\u7117\u725b\u8089\u53ef\u80fd\u542b\u6709\u8f83\u9ad8\u7684\u94a0\u548c\u6f5c\u5728\u7684\u6dfb\u52a0\u6cb9\u8102\uff0c\u9700\u6ce8\u610f\u70f9\u996a\u65b9\u5f0f\u3002", "\u7cd9\u7c73\u996d\u4efd\u91cf\u8f83\u5c11\uff0c\u53ef\u80fd\u4e0d\u8db3\u4ee5\u63d0\u4f9b\u6301\u7eed\u80fd\u91cf\uff0c\u9700\u5173\u6ce8\u6574\u4f53\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u3002"], "improvementTips": ["\u9009\u62e9\u84b8\u3001\u716e\u3001\u70e4\u6216\u7a7a\u6c14\u70b8\u7684\u725b\u8089\uff0c\u907f\u514d\u6cb9\u70b8\u6216\u91cd\u6cb9\u8c03\u5473\u3002", "\u5efa\u8bae\u6c99\u62c9\u9171\u9009\u62e9\u4f4e\u8102\u6cb9\u918b\u6c41\u6216\u67e0\u6aac\u6c41\uff0c\u907f\u514d\u9ad8\u70ed\u91cf\u6c99\u62c9\u9171\u3002", "\u53ef\u9002\u91cf\u589e\u52a0\u7cd9\u7c73\u996d\u7684\u6bd4\u4f8b\uff0c\u6216\u642d\u914d\u66f4\u591a\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\u6765\u6e90\uff08\u5982\u85dc\u9ea6\u3001\u71d5\u9ea6\uff09\u6765\u63d0\u5347\u9971\u8179\u611f\u548c\u80fd\u91cf\u7a33\u5b9a\u6027\u3002", "\u53ef\u4ee5\u5728\u6c99\u62c9\u4e2d\u52a0\u5165\u5176\u4ed6\u975e\u6dc0\u7c89\u7c7b\u852c\u83dc\uff08\u5982\u5723\u5973\u679c\u3001\u9ec4\u74dc\u3001\u5f69\u6912\uff09\u4ee5\u589e\u52a0\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\u591a\u6837\u6027\u3002", "\u8003\u8651\u5c06\u9e21\u86cb\u4f5c\u4e3a\u86cb\u767d\u8d28\u6765\u6e90\u7684\u4e00\u90e8\u5206\uff0c\u800c\u4e0d\u662f\u4f5c\u4e3a\u5355\u72ec\u7684\u914d\u6599\uff0c\u4f8b\u5982\u716e\u9e21\u86cb\u5207\u5757\u52a0\u5165\u6c99\u62c9\u4e2d\u3002"]}','2025-08-20 09:54:19');
INSERT INTO meal_logs VALUES(509,173,'dinner','虾仁西兰花, 肉沫蒸蛋, 上海青, 半份紫米饭 (660 kcal)',NULL,'{"generatedMealName": "\u5bb6\u5e38\u84b8\u86cb\u7092\u65f6\u852c\u914d\u7d2b\u7c73\u996d", "estimatedCalories": 660, "estimatedProteinG": 35.0, "estimatedCarbsG": 60.0, "estimatedFatG": 30.0, "description": "\u8fd9\u987f\u665a\u9910\u5305\u62ec\u4e00\u4efd\u867e\u4ec1\u897f\u5170\u82b1\uff0c\u4e3b\u8981\u7684\u98df\u6750\u662f\u867e\u4ec1\u548c\u897f\u5170\u82b1\uff0c\u53ef\u80fd\u7ecf\u8fc7\u6e05\u7092\u6216\u849c\u84c9\u7092\u3002\u53e6\u4e00\u9053\u662f\u8089\u6cab\u84b8\u86cb\uff0c\u7531\u9e21\u86cb\u6db2\u548c\u8089\u672b\u6df7\u5408\u84b8\u5236\u800c\u6210\u3002\u4e0a\u6d77\u9752\u4f5c\u4e3a\u7eff\u8272\u852c\u83dc\uff0c\u53ef\u80fd\u7ecf\u8fc7\u712f\u6c34\u6216\u6e05\u7092\u3002\u4e3b\u98df\u4e3a\u534a\u4efd\u7d2b\u7c73\u996d\u3002", "tags": ["\u5747\u8861\u996e\u98df", "\u86cb\u767d\u8d28", "\u852c\u83dc", "\u590d\u5408\u78b3\u6c34", "\u9002\u91cf\u8102\u80aa"], "identifiedIngredients": ["\u867e\u4ec1", "\u897f\u5170\u82b1", "\u9e21\u86cb", "\u8089\u672b", "\u4e0a\u6d77\u9752", "\u7d2b\u7c73\u996d"], "dominantColors": ["\u7eff\u8272", "\u767d\u8272", "\u6a59\u8272", "\u7d2b\u8272"], "cuisineStyle": "\u5bb6\u5e38\u83dc", "fatLossRating": 7, "fatLossAdvantages": ["\u63d0\u4f9b\u4f18\u8d28\u86cb\u767d\u8d28\uff08\u867e\u4ec1\u3001\u9e21\u86cb\u3001\u8089\u672b\uff09\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u548c\u7ef4\u6301\u808c\u8089\u91cf\u3002", "\u542b\u6709\u4e30\u5bcc\u7684\u81b3\u98df\u7ea4\u7ef4\u548c\u7ef4\u751f\u7d20\uff08\u897f\u5170\u82b1\u3001\u4e0a\u6d77\u9752\uff09\uff0c\u4fc3\u8fdb\u80a0\u9053\u5065\u5eb7\u3002", "\u7d2b\u7c73\u996d\u662f\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff0c\u76f8\u6bd4\u7cbe\u7c73\uff0c\u6d88\u5316\u5438\u6536\u66f4\u6162\uff0c\u6709\u52a9\u4e8e\u8840\u7cd6\u7a33\u5b9a\u3002", "\u84b8\u86cb\u7684\u70f9\u996a\u65b9\u5f0f\u76f8\u5bf9\u5065\u5eb7\uff0c\u51cf\u5c11\u4e86\u6cb9\u8102\u6444\u5165\u3002"], "fatLossDisadvantages": ["\u8089\u6cab\u84b8\u86cb\u4e2d\u7684\u8089\u672b\u53ef\u80fd\u5e26\u6709\u4e00\u5b9a\u8102\u80aa\uff0c\u5982\u679c\u9009\u62e9\u80a5\u8089\u6bd4\u4f8b\u8f83\u9ad8\u7684\u8089\u672b\uff0c\u4f1a\u589e\u52a0\u8102\u80aa\u6444\u5165\u3002", "\u867e\u4ec1\u897f\u5170\u82b1\u548c\u4e0a\u6d77\u9752\u7684\u70f9\u996a\u65b9\u5f0f\uff08\u5982\u662f\u5426\u7528\u6cb9\u3001\u7528\u6cb9\u91cf\uff09\u53ef\u80fd\u5f71\u54cd\u6574\u4f53\u8102\u80aa\u542b\u91cf\uff0c\u5982\u679c\u70f9\u996a\u65f6\u7528\u6cb9\u8f83\u591a\uff0c\u5219\u4e0d\u5229\u4e8e\u51cf\u8102\u3002", "\u7d2b\u7c73\u996d\u867d\u7136\u662f\u590d\u5408\u78b3\u6c34\uff0c\u4f46\u534a\u4efd\u7684\u91cf\uff08660kcal\u7684\u603b\u70ed\u91cf\uff09\u76f8\u5bf9\u8f83\u9ad8\uff0c\u5982\u679c\u51cf\u8102\u76ee\u6807\u662f\u4f4e\u78b3\u6c34\uff0c\u53ef\u80fd\u9700\u8981\u8c03\u6574\u4efd\u91cf\u3002"], "improvementTips": ["\u4f18\u5316\u84b8\u86cb\uff1a\u4f7f\u7528\u7626\u8089\u672b\uff08\u5982\u9e21\u80f8\u8089\u672b\u6216\u7626\u732a\u8089\u672b\uff09\u5236\u4f5c\u8089\u6cab\u84b8\u86cb\uff0c\u5e76\u5c3d\u91cf\u51cf\u5c11\u8089\u672b\u7684\u6cb9\u91cf\u3002", "\u63a7\u5236\u852c\u83dc\u70f9\u996a\u7528\u6cb9\uff1a\u867e\u4ec1\u897f\u5170\u82b1\u548c\u4e0a\u6d77\u9752\u5c3d\u91cf\u91c7\u7528\u712f\u6c34\u3001\u84b8\u6216\u5c11\u6cb9\u5feb\u7092\u7684\u65b9\u5f0f\uff0c\u907f\u514d\u8fc7\u591a\u6cb9\u70b8\u6216\u7206\u7092\u3002", "\u8c03\u6574\u4e3b\u98df\u4efd\u91cf\uff1a\u5982\u679c\u51cf\u8102\u671f\u95f4\u9700\u8981\u63a7\u5236\u78b3\u6c34\u6444\u5165\uff0c\u53ef\u4ee5\u5c06\u7d2b\u7c73\u996d\u7684\u4efd\u91cf\u51cf\u5c11\uff0c\u6216\u7528\u7b49\u91cf\u84b8\u852c\u83dc\uff08\u5982\u82b1\u83dc\uff09\u66ff\u4ee3\u90e8\u5206\u4e3b\u98df\u3002", "\u589e\u52a0\u98df\u6750\u591a\u6837\u6027\uff1a\u53ef\u4ee5\u5728\u9910\u98df\u4e2d\u52a0\u5165\u5c11\u91cf\u575a\u679c\u6216\u79cd\u5b50\uff08\u5982\u5947\u4e9a\u7c7d\u3001\u4e9a\u9ebb\u7c7d\uff09\u589e\u52a0\u5065\u5eb7\u8102\u80aa\u548c\u81b3\u98df\u7ea4\u7ef4\uff0c\u4f4