INSERT INTO meal_logs VALUES(526,174,'dinner','三文鱼牛柳藜麦沙拉: 这是一份包含三文鱼、牛柳、藜麦、西兰花、南瓜、胡萝卜、玉米、红豆和半颗水煮蛋的沙拉。配有少量酱汁和辣椒粉。蔬菜种类丰富，蛋白质来源多样，营养均衡。','meals/2025/08/user_2_meals_1755686832.jpg','{"generatedMealName": "\u4e09\u6587\u9c7c\u725b\u67f3\u85dc\u9ea6\u6c99\u62c9", "estimatedCalories": 550, "estimatedProteinG": 45.0, "estimatedCarbsG": 35.0, "estimatedFatG": 25.0, "description": "\u4e00\u4efd\u5305\u542b\u70e4\u6216\u714e\u4e09\u6587\u9c7c\u5757\u3001\u5c11\u91cf\u714e\u725b\u67f3\u5757\u3001\u716e\u719f\u7684\u85dc\u9ea6\u3001\u897f\u5170\u82b1\u3001\u5357\u74dc\u3001\u80e1\u841d\u535c\u3001\u7389\u7c73\u7c92\u3001\u7ea2\u8c46\u548c\u534a\u9897\u6c34\u716e\u86cb\u7684\u6c99\u62c9\u3002\u6c99\u62c9\u4e2d\u53ef\u80fd\u8fd8\u542b\u6709\u5c11\u91cf\u7528\u4e8e\u8c03\u5473\u7684\u9171\u6c41\u548c\u6492\u4e0a\u7684\u8fa3\u6912\u7c89\u3002", "tags": ["\u9ad8\u86cb\u767d", "\u5747\u8861\u8425\u517b", "\u852c\u83dc\u4e30\u5bcc", "\u5065\u5eb7\u8102\u80aa"], "identifiedIngredients": ["\u4e09\u6587\u9c7c", "\u725b\u67f3", "\u85dc\u9ea6", "\u897f\u5170\u82b1", "\u5357\u74dc", "\u80e1\u841d\u535c", "\u7389\u7c73", "\u7ea2\u8c46", "\u6c34\u716e\u86cb", "\u9171\u6c41", "\u8fa3\u6912\u7c89"], "dominantColors": ["\u6a59\u8272", "\u7eff\u8272", "\u7ea2\u8272", "\u9ec4\u8272"], "cuisineStyle": "\u878d\u5408\u83dc", "fatLossRating": 8, "fatLossAdvantages": ["\u63d0\u4f9b\u4f18\u8d28\u86cb\u767d\u8d28\uff08\u4e09\u6587\u9c7c\u3001\u725b\u67f3\u3001\u9e21\u86cb\uff09\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u548c\u7ef4\u6301\u808c\u8089\u91cf\u3002", "\u85dc\u9ea6\u662f\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff0c\u63d0\u4f9b\u6301\u7eed\u80fd\u91cf\uff0c\u4e14\u5bcc\u542b\u7ea4\u7ef4\u3002", "\u852c\u83dc\u79cd\u7c7b\u4e30\u5bcc\uff08\u897f\u5170\u82b1\u3001\u5357\u74dc\u3001\u80e1\u841d\u535c\uff09\uff0c\u63d0\u4f9b\u81b3\u98df\u7ea4\u7ef4\u3001\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\uff0c\u6709\u52a9\u4e8e\u6d88\u5316\u548c\u589e\u52a0\u9971\u8179\u611f\u3002", "\u4e09\u6587\u9c7c\u542b\u6709\u5065\u5eb7\u7684Omega-3\u8102\u80aa\u9178\uff0c\u5bf9\u8eab\u4f53\u6709\u76ca\u3002", "\u7ea2\u8c46\u548c\u7389\u7c73\u63d0\u4f9b\u4e86\u989d\u5916\u7684\u78b3\u6c34\u5316\u5408\u7269\u548c\u7ea4\u7ef4\u3002"], "fatLossDisadvantages": ["\u725b\u67f3\u548c\u4e09\u6587\u9c7c\u7684\u70f9\u996a\u65b9\u5f0f\uff08\u5982\u714e\uff09\u53ef\u80fd\u5e26\u6765\u989d\u5916\u6cb9\u8102\uff0c\u9700\u8981\u6ce8\u610f\u3002", "\u9171\u6c41\u662f\u6f5c\u5728\u7684\u9ad8\u70ed\u91cf\u3001\u9ad8\u7cd6\u3001\u9ad8\u94a0\u6765\u6e90\uff0c\u53ef\u80fd\u5f71\u54cd\u6574\u4f53\u51cf\u8102\u6548\u679c\u3002", "\u7389\u7c73\u548c\u5357\u74dc\u7684\u6dc0\u7c89\u542b\u91cf\u76f8\u5bf9\u8f83\u9ad8\uff0c\u9700\u8981\u6ce8\u610f\u6444\u5165\u91cf\u3002"], "improvementTips": ["\u5efa\u8bae\u5c06\u4e09\u6587\u9c7c\u548c\u725b\u67f3\u6539\u4e3a\u70e4\u3001\u84b8\u6216\u6c34\u716e\u7684\u65b9\u5f0f\uff0c\u4ee5\u51cf\u5c11\u70f9\u996a\u7528\u6cb9\u3002", "\u9009\u62e9\u6e05\u6de1\u7684\u6c99\u62c9\u9171\uff0c\u5982\u67e0\u6aac\u6c41\u3001\u6a44\u6984\u6cb9\uff08\u5c11\u91cf\uff09\u3001\u918b\u3001\u82a5\u672b\u9171\u7b49\uff0c\u6216\u5c06\u9171\u6c41\u5206\u5f00\u653e\u7f6e\uff0c\u6839\u636e\u4e2a\u4eba\u53e3\u5473\u5c11\u91cf\u6dfb\u52a0\u3002", "\u63a7\u5236\u9171\u6c41\u7684\u7528\u91cf\uff0c\u907f\u514d\u8fc7\u591a\u7684\u7cd6\u5206\u548c\u8102\u80aa\u6444\u5165\u3002", "\u5982\u9700\u589e\u52a0\u9971\u8179\u611f\uff0c\u53ef\u9002\u91cf\u589e\u52a0\u897f\u5170\u82b1\u3001\u83e0\u83dc\u7b49\u4f4e\u70ed\u91cf\u9ad8\u7ea4\u7ef4\u852c\u83dc\u7684\u6bd4\u4f8b\uff0c\u6216\u589e\u52a0\u4e00\u4efd\u53bb\u76ae\u9e21\u80f8\u8089\u3002", "\u6ce8\u610f\u6bcf\u79cd\u98df\u6750\u7684\u4efd\u91cf\uff0c\u7279\u522b\u662f\u85dc\u9ea6\u3001\u7389\u7c73\u548c\u5357\u74dc\uff0c\u907f\u514d\u8fc7\u91cf\u6444\u5165\u78b3\u6c34\u5316\u5408\u7269\u3002"]}','2025-08-20 10:47:20');
