INSERT INTO meal_logs VALUES(542,174,'lunch','清汤锅物配绿叶菜菌菇: 这是一份以清汤锅底为基础的午餐，选择藤椒鸡肉和鲜鱼片作为蛋白质来源，搭配大量绿叶菜和菌菇。放弃了店家蘸料，选择自制醋蒜酱油汁。主食未选择，只食用蔬菜和蛋白质，不喝汤。',NULL,'{"generatedMealName": "\u6e05\u6c64\u9e21\u8089\u9c7c\u7247\u852c\u83dc\u83cc\u83c7\u9505", "estimatedCalories": 350, "estimatedProteinG": 45.0, "estimatedCarbsG": 15.0, "estimatedFatG": 12.0, "description": "\u8fd9\u4efd\u5348\u9910\u662f\u4e00\u4efd\u4ee5\u6e05\u6c64\u4e3a\u5e95\u7684\u9505\u7269\uff0c\u4e3b\u8981\u5305\u542b\u85e4\u6912\u9e21\u8089\u3001\u9c9c\u9c7c\u7247\u3001\u5927\u91cf\u7684\u7eff\u53f6\u852c\u83dc\uff08\u5982\u83e0\u83dc\u3001\u751f\u83dc\uff09\u548c\u591a\u79cd\u83cc\u83c7\uff08\u5982\u9999\u83c7\u3001\u91d1\u9488\u83c7\uff09\u3002\u7528\u6237\u8868\u793a\u653e\u5f03\u4e86\u5e97\u5bb6\u7684\u8638\u6599\uff0c\u81ea\u884c\u8c03\u914d\u4e86\u918b\u849c\u9171\u6cb9\u6c41\uff0c\u5e76\u4e14\u6ca1\u6709\u98df\u7528\u4e3b\u98df\uff0c\u4e5f\u6ca1\u6709\u559d\u6c64\u3002\u918b\u849c\u9171\u6cb9\u6c41\u7684\u8c03\u914d\u53ef\u80fd\u542b\u6709\u9171\u6cb9\u3001\u918b\u3001\u849c\u672b\u7b49\u3002", "tags": ["\u9ad8\u86cb\u767d", "\u4f4e\u78b3\u6c34", "\u5bcc\u542b\u7ea4\u7ef4", "\u4f4e\u8102", "\u5065\u5eb7\u5348\u9910", "\u81ea\u5236\u9171\u6599", "\u852c\u83dc\u4e30\u5bcc"], "identifiedIngredients": ["\u6e05\u6c64\u9505\u5e95", "\u85e4\u6912\u9e21\u8089", "\u9c9c\u9c7c\u7247", "\u7eff\u53f6\u852c\u83dc", "\u83cc\u83c7", "\u918b", "\u849c", "\u9171\u6cb9"], "dominantColors": ["\u7eff\u8272", "\u767d\u8272", "\u68d5\u8272"], "cuisineStyle": "\u4e2d\u5f0f", "fatLossRating": 9, "fatLossAdvantages": ["\u86cb\u767d\u8d28\u542b\u91cf\u9ad8\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u548c\u7ef4\u6301\u808c\u8089\u91cf\u3002", "\u852c\u83dc\u548c\u83cc\u83c7\u63d0\u4f9b\u4e30\u5bcc\u7684\u81b3\u98df\u7ea4\u7ef4\uff0c\u4fc3\u8fdb\u80a0\u9053\u5065\u5eb7\uff0c\u589e\u52a0\u9971\u8179\u611f\uff0c\u6709\u52a9\u4e8e\u63a7\u5236\u98df\u6b32\u3002", "\u9009\u62e9\u6e05\u6c64\u9505\u5e95\uff0c\u76f8\u6bd4\u4e8e\u9ebb\u8fa3\u6216\u6d53\u6cb9\u8d64\u9171\u7684\u9505\u5e95\uff0c\u70ed\u91cf\u548c\u8102\u80aa\u542b\u91cf\u8f83\u4f4e\u3002", "\u653e\u5f03\u5e97\u5bb6\u9ad8\u70ed\u91cf\u3001\u9ad8\u8102\u80aa\u7684\u8638\u6599\uff0c\u5e76\u9009\u62e9\u4f4e\u70ed\u91cf\u7684\u81ea\u5236\u918b\u849c\u9171\u6cb9\u6c41\uff0c\u6709\u6548\u63a7\u5236\u4e86\u989d\u5916\u6cb9\u8102\u6444\u5165\u3002", "\u4e0d\u98df\u7528\u4e3b\u98df\uff0c\u663e\u8457\u964d\u4f4e\u4e86\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\uff0c\u6709\u5229\u4e8e\u63a7\u5236\u8840\u7cd6\u6ce2\u52a8\u548c\u4fc3\u8fdb\u8102\u80aa\u5206\u89e3\u3002", "\u4e0d\u559d\u6c64\uff0c\u907f\u514d\u4e86\u6c64\u4e2d\u53ef\u80fd\u6eb6\u89e3\u7684\u6cb9\u8102\u548c\u94a0\uff0c\u8fdb\u4e00\u6b65\u964d\u4f4e\u70ed\u91cf\u548c\u94a0\u6444\u5165\u3002"], "fatLossDisadvantages": ["\u9171\u6cb9\u53ef\u80fd\u542b\u6709\u8f83\u9ad8\u7684\u94a0\uff0c\u8fc7\u91cf\u6444\u5165\u53ef\u80fd\u5bfc\u81f4\u6c34\u80bf\uff0c\u867d\u7136\u5728\u6b64\u9910\u4e2d\u91cf\u5e94\u8be5\u4e0d\u5927\uff0c\u4f46\u4ecd\u9700\u6ce8\u610f\u3002", "\u867d\u7136\u662f\u81ea\u5236\u9171\u6599\uff0c\u4f46\u5177\u4f53\u7528\u6cb9\u91cf\u548c\u7cd6\u91cf\u4e0d\u660e\uff0c\u53ef\u80fd\u5b58\u5728\u6f5c\u5728\u70ed\u91cf\u589e\u52a0\u7684\u98ce\u9669\uff08\u4f46\u57fa\u4e8e\u63cf\u8ff0\uff0c\u6b64\u98ce\u9669\u8f83\u4f4e\uff09\u3002"], "improvementTips": ["\u7ee7\u7eed\u4fdd\u6301\u81ea\u5236\u4f4e\u5361\u9171\u6599\u7684\u4e60\u60ef\uff0c\u5e76\u786e\u4fdd\u9171\u6cb9\u7684\u7528\u91cf\u9002\u4e2d\uff0c\u63a7\u5236\u94a0\u7684\u6444\u5165\u3002", "\u5982\u679c\u6709\u53ef\u80fd\uff0c\u53ef\u4ee5\u54a8\u8be2\u5e97\u5bb6\u6216\u81ea\u884c\u786e\u8ba4\u9e21\u8089\u548c\u9c7c\u7247\u662f\u5426\u7ecf\u8fc7\u989d\u5916\u814c\u5236\u6216\u8c03\u5473\uff0c\u4ee5\u907f\u514d\u4e0d\u5fc5\u8981\u7684\u8102\u80aa\u548c\u94a0\u3002", "\u786e\u4fdd\u6444\u5165\u7684\u852c\u83dc\u79cd\u7c7b\u591a\u6837\uff0c\u4ee5\u83b7\u53d6\u66f4\u5168\u9762\u7684\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\u3002", "\u672a\u6765\u53ef\u4ee5\u5c06\u5c11\u91cf\u7c97\u7cae\uff08\u5982\u4e00\u5c0f\u4efd\u6742\u7cae\u996d\u6216\u7cd9\u7c73\u996d\uff09\u7eb3\u5165\u5348\u9910\uff0c\u4ee5\u63d0\u4f9b\u66f4\u6301\u4e45\u7684\u80fd\u91cf\u548c\u66f4\u5168\u9762\u7684\u8425\u517b\uff0c\u53ea\u8981\u603b\u91cf\u63a7\u5236\u5f97\u5f53\u3002", "\u70f9\u996a\u65f6\u5c3d\u91cf\u9009\u62e9\u5c11\u6cb9\u5c11\u76d0\u7684\u8c03\u5473\u65b9\u5f0f\uff0c\u6bd4\u5982\u84b8\u3001\u716e\u3001\u7096\u3002", "\u5982\u679c\u89c9\u5f97\u9971\u8179\u611f\u4e0d\u8db3\uff0c\u53ef\u4ee5\u9002\u91cf\u589e\u52a0\u4e00\u4efd\u4f4e\u8102\u5976\u5236\u54c1\uff08\u5982\u65e0\u7cd6\u9178\u5976\uff09\u4f5c\u4e3a\u52a0\u9910\u3002"]}','2025-08-21 10:15:28');
