INSERT INTO meal_logs VALUES(576,188,'breakfast','脱脂牛奶鸡蛋玉米黄瓜早餐: 这是一顿简单的早餐，包含一杯脱脂牛奶，一个鸡蛋，一块煮玉米，以及拌黄瓜。这顿饭提供适量的蛋白质、碳水化合物和少量脂肪，适合作为轻盈的早餐选择。',NULL,'{"generatedMealName": "\u8131\u8102\u725b\u5976\u9e21\u86cb\u7389\u7c73\u9ec4\u74dc\u65e9\u9910", "estimatedCalories": 280, "estimatedProteinG": 20.0, "estimatedCarbsG": 30.0, "estimatedFatG": 8.0, "description": "\u8fd9\u662f\u4e00\u987f\u5305\u542b\u4e00\u676f\u8131\u8102\u725b\u5976\u3001\u4e00\u4e2a\u716e\u9e21\u86cb\u3001\u4e00\u5c0f\u5757\u716e\u7389\u7c73\u548c\u62cc\u9ec4\u74dc\u7684\u65e9\u9910\u3002\u6574\u4f53\u989c\u8272\u4ee5\u767d\u8272\u3001\u9ec4\u8272\u3001\u7eff\u8272\u4e3a\u4e3b\uff0c\u98df\u6750\u6e05\u65b0\u3002", "tags": ["\u4f4e\u8102", "\u9ad8\u86cb\u767d", "\u4f4eGI", "\u65e9\u9910", "\u5065\u5eb7"], "identifiedIngredients": ["\u8131\u8102\u725b\u5976", "\u9e21\u86cb", "\u7389\u7c73", "\u9ec4\u74dc"], "dominantColors": ["white", "yellow", "green"], "cuisineStyle": "\u5bb6\u5e38", "fatLossRating": 8, "fatLossAdvantages": ["\u63d0\u4f9b\u4f18\u8d28\u86cb\u767d\u8d28\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u548c\u7ef4\u6301\u808c\u8089\u91cf\u3002", "\u542b\u6709\u9002\u91cf\u7684\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff0c\u63d0\u4f9b\u80fd\u91cf\u4e14\u9971\u8179\u611f\u8f83\u5f3a\u3002", "\u8131\u8102\u725b\u5976\u8102\u80aa\u542b\u91cf\u4f4e\uff0c\u7b26\u5408\u51cf\u8102\u9700\u6c42\u3002", "\u9ec4\u74dc\u542b\u6c34\u91cf\u9ad8\uff0c\u70ed\u91cf\u4f4e\uff0c\u4e14\u5bcc\u542b\u81b3\u98df\u7ea4\u7ef4\u3002", "\u70f9\u996a\u65b9\u5f0f\u4ee5\u6c34\u716e\u4e3a\u4e3b\uff0c\u51cf\u5c11\u4e0d\u5fc5\u8981\u7684\u6cb9\u8102\u6444\u5165\u3002"], "fatLossDisadvantages": ["\u7389\u7c73\u4f5c\u4e3a\u4e3b\u98df\uff0c\u867d\u7136\u662f\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff0c\u4f46\u76f8\u8f83\u4e8e\u7eff\u53f6\u852c\u83dc\uff0c\u78b3\u6c34\u5316\u5408\u7269\u542b\u91cf\u8f83\u9ad8\u3002", "\u7f3a\u4e4f\u591a\u6837\u7684\u852c\u83dc\u79cd\u7c7b\uff0c\u81b3\u98df\u7ea4\u7ef4\u548c\u5fae\u91cf