INSERT INTO meal_logs VALUES(577,188,'lunch','三文鱼牛柳藜麦沙拉: 这是一份健康的三文鱼牛柳藜麦沙拉，包含三文鱼、牛柳、藜麦、西兰花、南瓜、胡萝卜、玉米、红豆、生菜等多种食材。牛柳淋有酱汁。另有一份辣椒粉作为调味品。','meals/2025/08/user_2_meals_1755827009.jpg','{"generatedMealName": "\u4e09\u6587\u9c7c\u725b\u67f3\u85dc\u9ea6\u6c99\u62c9", "estimatedCalories": 650, "estimatedProteinG": 45.0, "estimatedCarbsG": 40.0, "estimatedFatG": 35.0, "description": "\u4e00\u4efd\u5305\u542b\u4e09\u6587\u9c7c\u3001\u725b\u67f3\u3001\u85dc\u9ea6\u3001\u897f\u5170\u82b1\u3001\u5357\u74dc\u3001\u80e1\u841d\u535c\u3001\u7389\u7c73\u3001\u7ea2\u8c46\u3001\u751f\u83dc\u7684\u6c99\u62c9\u3002\u725b\u67f3\u6dcb\u6709\u9171\u6c41\uff0c\u5e76\u914d\u6709\u8fa3\u6912\u7c89\u4f5c\u4e3a\u8c03\u5473\u54c1\u3002", "tags": ["\u9ad8\u86cb\u767d", "\u590d\u5408\u78b3\u6c34", "\u591a\u79cd\u852c\u83dc", "\u5065\u5eb7\u8102\u80aa", "\u51cf\u8102\u9910"], "identifiedIngredients": ["\u4e09\u6587\u9c7c", "\u725b\u67f3", "\u85dc\u9ea6", "\u897f\u5170\u82b1", "\u5357\u74dc", "\u80e1\u841d\u535c", "\u7389\u7c73", "\u7ea2\u8c46", "\u751f\u83dc", "\u9171\u6c41", "\u8fa3\u6912\u7c89"], "dominantColors": ["\u7eff\u8272", "\u6a59\u8272", "\u9ec4\u8272", "\u7c89\u8272", "\u68d5\u8272"], "cuisineStyle": "\u6df7\u5408/\u897f\u5f0f", "fatLossRating": 7, "fatLossAdvantages": ["\u63d0\u4f9b\u4f18\u8d28\u86cb\u767d\u8d28\uff08\u4e09\u6587\u9c7c\u3001\u725b\u67f3\uff09\uff0c\u6709\u52a9\u4e8e\u7ef4\u6301\u9971\u8179\u611f\u548c\u808c\u8089\u751f\u957f\u3002", "\u5bcc\u542b\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff08\u85dc\u9ea6\uff09\uff0c\u80fd\u91cf\u91ca\u653e\u7f13\u6162\uff0c\u6709\u52a9\u4e8e\u7a33\u5b9a\u8840\u7cd6\u3002", "\u5305\u542b\u591a\u79cd\u852c\u83dc\uff08\u897f\u5170\u82b1\u3001\u80e1\u841d\u535c\u3001\u751f\u83dc\u7b49\uff09\uff0c\u63d0\u4f9b\u81b3\u98df\u7ea4\u7ef4\u3001\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\uff0c\u4fc3\u8fdb\u80a0\u9053\u5065\u5eb7\uff0c\u589e\u52a0\u9971\u8179\u611f\u3002", "\u4e09\u6587\u9c7c\u63d0\u4f9b\u5065\u5eb7\u7684Omega-3\u8102\u80aa\u9178\uff0c