548c\u70ed\u91cf\u3002"], "improvementTips": ["\u63a7\u5236\u5168\u9ea6\u5410\u53f8\u7684\u4efd\u91cf\uff0c\u4e00\u7247\uff08\u7ea630\u514b\uff09\u662f\u5408\u7406\u7684\u3002\u5982\u679c\u611f\u89c9\u80fd\u91cf\u4e0d\u8db3\uff0c\u53ef\u8003\u8651\u589e\u52a0\u86cb\u767d\u8d28\u6765\u6e90\u5982\u5c11\u91cf\u575a\u679c\u3002", "\u786e\u4fdd\u51c9\u62cc\u9ec4\u74dc\u548c\u897f\u7ea2\u67ff\u7684\u8c03\u5473\u5c3d\u91cf\u6e05\u6de1\uff0c\u907f\u514d\u4f7f\u7528\u9ad8\u6cb9\u6c99\u62c9\u9171\uff0c\u53ef\u9009\u62e9\u5c11\u91cf\u918b\u3001\u67e0\u6aac\u6c41\u3001\u9ed1\u80e1\u6912\u7b49\u3002", "\u53ef\u4ee5\u8003\u8651\u5c06\u6c34\u716e\u86cb\u6362\u6210\u84b8\u86cb\u6216\u8377\u5305\u86cb\uff08\u4e0d\u52a0\u6cb9\uff09\uff0c\u6216\u8005\u589e\u52a0\u9e21\u86cb\u7684\u91cf\u3002", "\u5982\u679c\u9700\u8981\u589e\u52a0\u9971\u8179\u611f\uff0c\u53ef\u4ee5\u8003\u8651\u5728\u65e9\u9910\u4e2d\u52a0\u5165\u5c11\u91cf\u5947\u4e9a\u7c7d\u6216\u4e9a\u9ebb\u7c7d\uff0c\u589e\u52a0\u81b3\u98df\u7ea4\u7ef4\u548c\u5065\u5eb7\u8102\u80aa\u3002"]}','2025-08-22 07:19:24');
INSERT INTO meal_logs VALUES(611,197,'lunch','清蒸鱼配黑米饭和炒鸡蛋: 一整条清蒸的鱼，鱼身完整，淋有少量汤汁，并撒有葱花。旁边有一碗黑米饭，米饭颗粒分明，色泽较深。另一碗是炒菜，主要成分是鸡蛋碎和一些黑色的食物颗粒（可能是榨菜或肉碎）以及葱段。','meals/2025/08/user_2_meals_1755847211.jpg','{"generatedMealName": "\u6e05\u84b8\u9c7c\u914d\u9ed1\u7c73\u996d\u53ca\u7092\u86cb", "estimatedCalories": 550, "estimatedProteinG": 40.0, "estimatedCarbsG": 50.0, "estimatedFatG": 25.0, "description": "\u4e00\u6574\u6761\u6e05\u84b8\u7684\u9c7c\uff0c\u9c7c\u8eab\u5b8c\u6574\uff0c\u6dcb\u6709\u5c11\u91cf\u6c64\u6c41\uff0c\u6492\u6709\u8471\u82b1\u3002\u65c1\u8fb9\u6709\u4e00\u7897\u9ed1\u7c73\u996d\uff0c\u7c73\u996d\u9897\u7c92\u5206\u660e\uff0c\u8272\u6cfd\u8f83\u6df1\u3002\u53e6\u4e00\u7897\u662f\u7092\u83dc\uff0c\u4e3b\u8981\u6210\u5206\u662f\u9e21\u86cb\u788e\u548c\u4e00\u4e9b\u9ed1\u8272\u7684\u98df\u7269\u9897\u7c92\uff08\u53ef\u80fd\u662f\u69a8\u83dc\u6216\u8089\u788e\uff09\u4ee5\u53ca\u8471\u6bb5\u3002", "tags": ["\u51cf\u8102", "\u5747\u8861\u8425\u517b", "\u86cb\u767d\u8d28", "\u590d\u5408\u78b3\u6c34", "\u9002\u91cf\u8102\u80aa"], "identifiedIngredients": ["\u6e05\u84b8\u9c7c", "\u9ed1\u7c73\u996d", "\u7092\u9e21\u86cb", "\u8471", "\u5c11\u91cf\u6c64\u6c41", "\u69a8\u83dc\u6216\u8089\u788e"], "dominantColors": ["\u767d\u8272", "\u9ed1\u8272", "\u7eff\u8272", "\u9ec4\u8272"], "cuisineStyle": "\u4e2d\u5f0f\u5bb6\u5e38", "fatLossRating": 7, "fatLossAdvantages": ["\u6e05\u84b8\u9c7c\u63d0\u4f9b\u4f18\u8d28\u52a8\u7269\u86cb\u767d\uff0c\u6709\u52a9\u4e8e\u589e\u52a0\u9971\u8179\u611f\u548c\u7ef4\u6301\u808c\u8089\u91cf\u3002", "\u9ed1\u7c73\u996d\u662f\u590d\u5408\u78b3\u6c34\u5316\u5408\u7269\uff0c\u6bd4\u7cbe\u5236\u767d\u7c73\u996d\u5347\u7cd6\u6307\u6570\u66f4\u4f4e\uff0c\u63d0\u4f9b\u6301\u4e45\u80fd\u91cf\u3002", "\u9ed1\u7c73\u996d\u5bcc\u542b\u81b3\u98df\u7ea4\u7ef4\uff0c\u6709\u52a9\u4e8e\u80a0\u9053\u5065\u5eb7\u548c\u63a7\u5236\u98df\u6b32\u3002", "\u9e21\u86cb\u662f\u4f18\u8d28\u86cb\u767d\u8d28\u6765\u6e90\uff0c\u4e14\u542b\u6709\u591a\u79cd\u7ef4\u751f\u7d20\u548c\u77ff\u7269\u8d28\u3002"], "fatLossDisadvantages": ["\u7092\u9e21\u86cb\u53ef\u80fd\u542b\u6709\u989d\u5916\u7684\u98df\u7528\u6cb9\uff0c\u589e\u52a0\u4e86\u8102\u80aa\u548c\u70ed\u91cf\u6444\u5165\u3002", "\u9ed1\u8272\u98df\u7269\u9897\u7c92\uff08\u5982\u69a8\u83dc\u6216\u8089\u788e\uff09\u5982\u679c\u542b\u6709\u8f83\u591a\u76d0\u5206\u6216\u8102\u80aa\uff0c\u4f1a\u589e\u52a0\u6574\u4f53\u6444\u5165\u3002", "\u9ed1\u7c73\u996d\u7684\u4efd\u91cf\u5982\u679c\u8fc7\u5927\uff0c\u53ef\u80fd\u5bfc\u81f4\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u8d85\u6807\u3002", "\u6574\u6761\u9c7c\u7684\u4efd\u91cf\u548c\u9c7c\u7684\u79cd\u7c7b\u672a\u77e5\uff0c\u53ef\u80fd\u5f71\u54cd\u5177\u4f53\u8425\u517b\u7d20\u4f30\u7b97\u3002"], "improvementTips": ["\u5efa\u8bae\u5c06\u7092\u9e21\u86cb\u6539\u4e3a\u6c34\u716e\u86cb\u6216\u84b8\u86cb\uff0c\u4ee5\u51cf\u5c11\u70f9\u996a\u7528\u6cb9\u3002", "\u660e\u786e\u9ed1\u8272\u98df\u7269\u9897\u7c92\u7684\u6210\u5206\uff0c\u5982\u4e3a\u69a8\u83dc\uff0c\u5efa\u8bae\u5c11\u91cf\u98df\u7528\u4ee5\u63a7\u5236\u94a0\u6444\u5165\uff1b\u5982\u4e3a\u8089\u788e\uff0c\u5efa\u8bae\u9009\u62e9\u7626\u8089\u3002", "\u63a7\u5236\u9ed1\u7c73\u996d\u7684\u4efd\u91cf\uff0c\u5efa\u8bae\u4e00\u5c0f\u7897\uff08\u7ea6100-120\u514b\u719f\u91cd\uff09\uff0c\u786e\u4fdd\u78b3\u6c34\u5316\u5408\u7269\u6444\u5165\u5408\u7406\u3002", "\u6e05\u84b8\u9c7c\u7684\u6c64\u6c41\u4e2d\u53ef\u80fd\u542b\u6709\u6cb9\u8102\u548c\u76d0\u5206\uff0c\u5efa\u8bae\u9002\u91cf\u996e\u7528\u6216\u5f03\u6389\u90e8\u5206\u3002", "\u589e\u52a0\u852c\u83dc\u6444\u5165\uff0c\u53ef\u4ee5\u5728\u6e05\u84b8\u9c7c\u65c1\u8fb9\u642d\u914d\u4e00\u4efd\u6e05\u7092\u6216\u51c9\u62cc\u7684\u7eff\u53f6\u852c\u83dc\uff0c\u589e\u52a0\u81b3\u98df\u7ea4\u7ef4\u548c\u7ef4\u751f\u7d20\u3002"]}','2025-08-22 07:20:19');
