PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
	id INTEGER NOT NULL, 
	username VARCHAR(50) NOT NULL, 
	email VARCHAR(100), 
	password_hash VARCHAR(255) NOT NULL, 
	age INTEGER, 
	gender VARCHAR(10), 
	height DECIMAL(5, 2), 
	initial_weight DECIMAL(5, 2), 
	activity_level VARCHAR(20), 
	gemini_api_key VARCHAR(255), 
	is_active BOOLEAN, 
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP), 
	updated_at DATETIME DEFAULT (CURRENT_TIMESTAMP), 
	PRIMARY KEY (id)
);
CREATE TABLE daily_logs (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	date DATE NOT NULL, 
	weight_kg DECIMAL(5, 2), 
	waist_cm DECIMAL(5, 2), 
	water_l DECIMAL(4, 2), 
	sleep_h DECIMAL(4, 2), 
	bmr DECIMAL(7, 2), 
	tdee DECIMAL(7, 2), 
	actual_intake DECIMAL(7, 2), 
	estimated_expenditure DECIMAL(7, 2), 
	protein_g DECIMAL(6, 2), 
	carbs_g DECIMAL(6, 2), 
	fat_g DECIMAL(6, 2), 
	calorie_deficit DECIMAL(7, 2), 
	activity TEXT, 
	summary TEXT, 
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP), 
	updated_at DATETIME DEFAULT (CURRENT_TIMESTAMP), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE analysis_reports (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	report_data JSON NOT NULL, 
	generated_at DATETIME DEFAULT (CURRENT_TIMESTAMP), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE chat_messages (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	role VARCHAR(10) NOT NULL, 
	text TEXT NOT NULL, 
	image_path VARCHAR(255), 
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE meal_logs (
	id INTEGER NOT NULL, 
	daily_log_id INTEGER NOT NULL, 
	meal_type VARCHAR(20) NOT NULL, 
	text TEXT NOT NULL, 
	image_path VARCHAR(255), 
	analysis_data JSON, 
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP), 
	PRIMARY KEY (id), 
	FOREIGN KEY(daily_log_id) REFERENCES daily_logs (id)
);
CREATE INDEX ix_users_id ON users (id);
CREATE UNIQUE INDEX ix_users_username ON users (username);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_daily_logs_id ON daily_logs (id);
CREATE INDEX ix_analysis_reports_id ON analysis_reports (id);
CREATE INDEX ix_chat_messages_id ON chat_messages (id);
CREATE INDEX ix_meal_logs_id ON meal_logs (id);
COMMIT;
